    "wordCount": 260,
    "estimatedMinutes": 3,
    "passagePlain": "豚が猪に向かって自慢をしました。「私ぐらい結構な身分はない。食べることから寝ることまですっかり人間に世話をしてもらって、ご馳走はイヤという程食べるからこんなに太っている。人と喧嘩をしなくてもいいから牙なんぞは入り用（注１）がない。私とお前さんとは親類だそうだが、同じ親類でもこんなに身分が違うものか。」\n猪はこれを聞くと笑いました。「人間というものはただでいつまでもご馳走（注２）を食わせて置くような親切なものじゃないよ。人の厄介になって威張るものは今にきっと罰が当たるから見ておいで。」\n猪の言ったことはとうとう本当になりました。豚はまもなく人間に殺されて食われてしまいました。\n〈夢野久作『豚と猪』による〉\n\n(注1) 入り用：用事のために必要なこと（さま）\n(注2) ご馳走：饗応すること。また、そのための立派な料理。",
    "passageRuby": "豚(ぶた)が猪(いのしし)に向(む)かって自慢(じまん)をしました。「私(わたし)ぐらい結構(けっこう)な身分(みぶん)はない。食(た)べることから寝(ね)ることまですっかり人間(にんげん)に世話(せわ)をしてもらって、ご馳走(ちそう)はイヤという程(ほど)食(た)べるからこんなに太(ふと)っている。人(ひと)と喧嘩(けんか)をしなくてもいいから牙(きば)なんぞは入り用(いりよう)（注１）がない。私(わたし)とお前(まえ)さんとは親類(しんるい)だそうだが、同(おな)じ親類(しんるい)でもこんなに身分(みぶん)が違(ちが)うものか。」\n猪(いのしし)はこれを聞(き)くと笑(わら)いました。「<u>人間(にんげん)というものはただでいつまでもご馳走(ちそう)（注２）を食(く)わせて置(お)くような親切(しんせつ)なものじゃないよ。人(ひと)の厄介(やっかい)になって威張(いば)るものは今(いま)にきっと罰(ばち)が当(あ)たるから見(み)ておいで。</u>」\n猪(いのしし)の言(い)ったことはとうとう本当(ほんとう)になりました。豚(ぶた)はまもなく人間(にんげん)に殺(ころ)されて食(く)われてしまいました。\n〈夢野久作(ゆめのきゅうさく)『豚(ぶた)と猪(いのしし)』による〉\n\n(注1) 入り用(いりよう)：用事(ようじ)のために必要(ひつよう)なこと（さま）\n(注2) ご馳走(ちそう)：饗応(きょうおう)すること。また、そのための立派(りっぱ)な料理(りょうり)。",
    "passageTrans": "돼지가 멧돼지에게 자랑을 늘어놓았습니다. \"나만큼 훌륭한 팔자도 없을 거야. 먹는 것부터 자는 것까지 전부 인간이 돌봐주고, 맛있는 음식은 물릴 정도로 먹으니 이렇게 살이 쪘지. 인간과 싸우지 않아도 되니 엄니 따위는 필요(주1)도 없어. 나와 자네는 친척이라던데, 같은 친척이라도 어쩜 이렇게 신세가 다를까.\"\n멧돼지는 이 말을 듣고 웃었습니다. \"인간이라는 존재는 공짜로 언제까지나 진수성찬(주2)을 먹여줄 만큼 친절한 존재가 아니야. 남의 신세를 지면서 거들먹거리는 자는 머지않아 반드시 천벌을 받을 테니 두고 보라고.\"\n멧돼지가 한 말은 결국 사실이 되었습니다. 돼지는 얼마 안 가 인간에게 도살당해 먹히고 말았습니다.\n〈유메노 규사쿠 『돼지와 멧돼지』에서〉\n\n(주1) 필요: 어떤 일이나 용도를 위해 필요한 상태\n(주2) 진수성찬: 극진히 대접하는 것, 또는 그를 위한 훌륭한 요리.",
