    "passagePlain": "下は、ある会社が取引先に向けて出した文書である。\n\n2018年8月22日\n\n株式会社 グッド チェアズ\n仕入部長 田中和夫様\n\n株式会社 家具通販のロウヤ\n営業部長 本田一郎\n\n(　　　　)\n\n拝啓\n貴社ますますご隆盛のことと存じます。\nさて、先般ご照会申し上げました貴社製品「らくらくチェア」の取引条件につきましては、さっそくに07月29日付文書番号00232号にてご回答をいただき、まことにありがとうございました。当社といたしましては、ぜひとも貴社製品を扱わせていただきたく存じますが、下記の点で若干のご配慮を賜ればとお伺い申し上げる次第でございます。\nなにとぞご検討のうえ、よろしくご返答のほどをお願い申し上げます。\n敬具\n\n記\n1. 支払い条件\n約束手形決済を90日後から120日後へ変更\n以上",
    "passageRuby": "下(した)は、ある会社(かいしゃ)が取引先(とりひきさき)に向(む)けて出(だ)した文書(ぶんしょ)である。\n\n2018年(ねん)8月(がつ)22日(にち)\n\n株式会社(かぶしきがいしゃ) グッド チェアズ\n仕入部長(しいれぶちょう) 田中和夫様(たなかかずおさま)\n\n株式会社(かぶしきがいしゃ) 家具通販(かぐつうはん)のロウヤ\n営業部長(えいぎょうぶちょう) 本田一郎(ほんだいちろう)\n\n(　　　　)\n\n拝啓(はいけい)\n貴社(きしゃ)ますますご隆盛(りゅうせい)のことと存(ぞん)じます。\nさて、先般(せんぱん)ご照会(しょうかい)申(もう)し上(あ)げました貴社製品(きしゃせいひん)「らくらくチェア」の取引条件(とりひきじょうけん)につきましては、さっそくに07月(がつ)29日付(にちづけ)文書番号(ぶんしょばんごう)00232号(ごう)にてご回答(かいとう)をいただき、まことにありがとうございました。当社(とうしゃ)といたしましては、ぜひとも貴社製品(きしゃせいひん)を扱(あつか)わせていただきたく存(ぞん)じますが、下記(かき)の点(てん)で若干(じゃっかん)のご配慮(はいりょ)を賜(たまわ)ればとお伺(うかが)い申(もう)し上(あ)げる次第(しだい)でございます。\nなにとぞご検討(けんとう)のうえ、よろしくご返答(へんとう)のほどをお願(ねが)い申(もう)し上(あ)げます。\n敬具(けいぐ)\n\n記(き)\n1. 支払(しはら)い条件(じょうけん)\n<u>約束手形決済(やくそくてがたけっさい)を90日後(にちご)から120日後(にちご)へ変更(へんこう)</u>\n以上(いじょう)",
    "passageTrans": "다음은 어느 회사가 거래처로 보낸 문서이다.\n\n2018년 8월 22일\n\n주식회사 굿 체어즈\n구매부장 다나카 가즈오 귀하\n\n주식회사 가구통신판매 로우야\n영업부장 혼다 이치로\n\n(　　　　)\n\n배복\n귀사의 무궁한 발전을 기원합니다.\n다름 아니라 지난번 문의드렸던 귀사 제품 '라쿠라쿠 체어'의 거래 조건에 대해서는 신속하게 7월 29일 자 문서번호 제00232호로 답변해 주셔서 대단히 감사했습니다. 당사로서는 부디 귀사 제품을 취급하고 싶습니다만, 아래 사항에 대해 약간의 배려를 베풀어 주셨으면 하여 여쭙는 바입니다.\n부디 검토해 주신 뒤, 회신 부탁드리겠습니다.\n경구\n\n기\n1. 지불 조건\n약속어음 결제를 90일 후에서 120일 후로 변경\n이상",
