    "source": "시나공 JLPT N2 독해 단문이해 04 (p.343)",
    "wordCount": 250,
    "estimatedMinutes": 3,
    "passagePlain": "アナログ志向とデジタル志向という区別は基本的には文学的な表現であり、新しいものがたまたま現在ではデジタルというイメージで総括できるからそのような表現が成立するに過ぎない。若い世代が古い世代に比べて新しいものに対しての受け入れが敏感で柔軟であるのは普遍性のあることかもしれないが、「新しいもの」＝「デジタル」という定義などありはしないのである。このように注意して全体像を考慮しなければ、文学的な表現のアナログとデジタルについても、木を見て森を見ずといったような判断の間違いや誤解が起きたりするのである。",
    "passageRuby": "アナログ志向(しこう)とデジタル志向(しこう)という区別(くべつ)は基本的(きほんてき)には文学的(ぶんがくてき)な表現(ひょうげん)であり、新(あたら)しいものがたまたま現在(げんざい)ではデジタルというイメージで総括(そうかつ)できるからそのような表現(ひょうげん)が成立(せいりつ)するに過(す)ぎない。若(わか)い世代(せだい)が古(ふる)い世代(せだい)に比(くら)べて新(あたら)しいものに対(たい)しての受(う)け入(い)れが敏感(びんかん)で柔軟(じゅうなん)であるのは普遍性(ふへんせい)のあることかもしれないが、<u>「新(あたら)しいもの」＝「デジタル」という定義(ていぎ)などありはしない</u>のである。このように注意(ちゅうい)して全体像(ぜんたいぞう)を考慮(こうりょ)しなければ、文学的(ぶんがくてき)な表現(ひょうげん)のアナログとデジタルについても、<u>木(き)を見(み)て森(もり)を見(み)ず</u>といったような判断(はんだん)の間違(まちが)いや誤解(ごかい)が起(お)きたりするのである。",
    "passageTrans": "아날로그 지향과 디지털 지향이라는 구별은 기본적으로는 문학적인 표현이며, 새로운 것이 때마침 현재에는 디지털이라는 이미지로 총괄될 수 있기 때문에 그러한 표현이 성립하는 것에 지나지 않는다. 젊은 세대가 기성세대에 비해 새로운 것을 민감하고 유연하게 받아들이는 것은 보편적인 현상일지 모르나, '새로운 것 = 디지털'이라는 정의 따위는 결코 존재하지 않는다. 이처럼 주의를 기울여 전체상을 고려하지 않는다면, 아날로그와 디지털이라는 문학적 표현에 대해서도 '나무만 보고 숲은 보지 못하는' 식의 그릇된 판단이나 오해가 빚어지게 되는 것이다.",
