    "wordCount": 620,
    "estimatedMinutes": 7,
    "passagePlain": "次の文章は「教育」に関する記事の一部である。二つの文章を読んで、後の問いに対する答えとして、最もよいものを選びなさい。\n\n[A]\n長い間、日本では詰め込み教育が行われ、それが絶対的な悪のように言われ続けてきましたが、詰め込み教育の全てが悪いわけではありません。詰め込んだ知識はすぐ忘れるというのも、必ずしも正しくはありません。例えば、学校のテストにおける一夜漬けと比べて大学受験レベルの暗記では、詰め込んだ時に使う頭の部分が違います。表面的な暗記だけで、大学受験レベルの膨大な量を覚えることなど出来ません。そこには必ずそれなりの理解力が伴うのです。たくさんのことを覚えるためには、理解することが近道であることに気付くわけです。このことに気付かない人たちは、まともに勉強したことがないのだろうと思います。問題なのは詰め込み自体ではなく、自分なりに深く理解する時間が足りないことなのです。\n\n[B]\n数年前に公的機関が行った調査の結果、国語も算数も記述式の問題に白紙回答の子供が3〜4割位はいたそうです。考えるためには自分なりに理解していることが大切ですが、それが出来ていなかったということです。これは、一方的に話を聞かされても考える力はつきにくい、ということを表していると思います。教えられたことが実になるためには、自分なりに理解する時間が必要なのです。またできる子供の解答も、自分なりに咀嚼して記述したものというよりは、どこかで聞いたような模範的なものになってしまう傾向にあるのです。もちろん模範的解答を踏み台にして、そこから将来的に伸びる可能性があることも確かではあります。これはあくまでも本人の意識次第です。",
    "passageRuby": "次(つぎ)の文章(ぶんしょう)は「教育(きょういく)」に関(かん)する記事(きじ)の一部(いちぶ)である。二(ふた)つの文章(ぶんしょう)を読(よ)んで、後(あと)の問(と)いに対(たい)する答(こた)えとして、最(もっと)もよいものを選(えら)びなさい。\n\n[A]\n長(なが)い間(あいだ)、日本(にほん)では詰め込み教育(つめこみきょういく)が行(おこな)われ、それが絶対的(ぜったいてき)な悪(あく)のように言(い)われ続(つづ)けてきましたが、詰め込み教育(つめこみきょういく)の全(すべ)てが悪(わる)いわけではありません。詰め込んだ知識(ちしき)はすぐ忘(わす)れるというのも、必(かなら)ずしも正(ただ)しくはあリません。例(たと)えば、学校(がっこう)のテストにおける一夜漬(いちやづ)けと比(くら)べて大学受験(だいがくじゅけん)レベルの暗記(あんき)では、詰め込んだ時(とき)に使(つか)う頭(あたま)の部分(ぶぶん)が違(ちが)います。表面的な暗記だけで、大学受験レベルの膨大な量を覚えることなど出来ません。そこには必(かなら)ずそれなりの理解力(りかいりょく)が伴(ともな)うのです。たくさんのことを覚(おぼ)えるためには、理解(りかい)することが近道(ちかみち)であることに気付(きづ)くわけです。このことに気付(きづ)かない人(ひと)たちは、まともに勉強(べんきょう)したことがないのだろうと思(おも)います。<u>問題(もんだい)なのは詰め込み自体(じたい)ではなく、自分(じぶん)なりに深(ふか)く理解(りかい)する時間(じかん)が足(た)りないことなのです</u>。\n\n[B]\n数年前(すうねんまえ)に公的機関(こうてききかん)が行(おこな)った調査(ちょうさ)の結果(けっか)、国語(こくご)も算数(さんすう)も記述式(きじゅつしき)の問題(もんだい)に白紙回答(はくしかいとう)の子供(こども)が3〜4割位(わりぐらい)はいたそうです。考(かんが)えるためには自分(じぶん)なりに理解(りかい)していることが大切(たいせつ)ですが、それが出来(でき)ていなかったということです。これは、一方的(いっぽうてき)に話(はなし)を聞(き)かされても考(かんが)える力(ちから)はつきにくい、ということを表(あらわ)していると思(おも)います。<u>教(おし)えられたことが実(み)になるためには、自分(じぶん)なりに理解(りかい)する時間(じかん)が必要(ひつよう)なのです</u>。またできる子供(こども)の解答(かいとう)も、自分(じぶん)なりに咀嚼(そしゃく)して記述(きじゅつ)したものというよりは、どこかで聞(き)いたような模範的(もはんてき)なものになってしまう傾向(けいこう)にあるのです。もちろん模範的解答(もはんてきかいとう)を踏(ふ)み台(だい)にして、そこから将来的(しょうらいてき)に伸(の)びる可能性(かのうせい)があることも確(たし)かではあります。これはあくまでも本人(ほんにん)の意識次第(いしきしだい)です。",
    "passageTrans": "다음 글은 '교육'에 관한 기사의 일부이다. 두 글을 읽고 뒤의 물음에 가장 알맞은 답을 고르시오.\n\n[A]\n오랜 세월 일본에서는 주입식 교육이 행해졌고 그것이 절대적인 악인 양 비판받아 왔지만, 주입식 교육의 모든 것이 나쁜 것은 아니다. 주입한 지식은 곧바로 잊어버린다는 통념 역시 반드시 옳지만은 않다. 예컨대 학교 시험의 벼락치기와 비교해 대입 수험 수준의 암기에서는 머리를 쓰는 방식 자체가 다르다. 표면적인 단순 암기만으로는 대입 수험의 방대한 양을 소화할 수 없다. 거기에는 반드시 상응하는 이해력이 수반되기 마련이다. 많은 양을 기억하기 위해서는 본질적인 이해가 지름길임을 깨닫게 된다. 이를 모르는 이들은 제대로 공부해 본 적이 없는 사람들일 것이다. 진정한 문제는 주입식 교육 그 자체가 아니라, 스스로 깊이 이해할 시간이 부족하다는 점에 있다.\n\n[B]\n몇 년 전 공적 기관이 시행한 조사 결과, 국어와 수학 모두 서술형 문항에 백지 답안을 낸 아이가 3~4할이나 되었다고 한다. 사고하기 위해서는 자기 나름의 이해가 선행되어야 하는데 그것이 결여되어 있었다는 방증이다. 이는 일방적으로 강의를 듣는 것만으로는 생각하는 힘이 길러지기 어렵다는 사실을 보여준다. 배운 지식이 살이 되기 위해서는 스스로 이해하고 정리할 시간이 필수적이다. 또한 성적이 우수한 아이들의 답안조차 스스로 곱씹어 서술했다기보다는 어디서 들은 모범 답안을 흉내 내는 경향이 짙다. 물론 그러한 모범 답안을 발판 삼아 장기적으로 도약할 가능성도 없지는 않겠으나, 이는 어디까지나 학습자 본인의 의식에 달려 있다.",
