    "wordCount": 960,
    "estimatedMinutes": 9,
    "passagePlain": "オーストリアのウィーン市のはずれに公園のように美しい墓地がある。そこにベートーヴェンの墓や、モーツァルトの墓があった。偉大な音楽家の生涯にふさわしく、心をこめ意匠された墓が晩春の花にかこまれているのを見た。ポーランドのワルシャワ市にはショパンの記念像があり、モスクワの街々にはプーシキンやゴーリキーら文学者の記念像が立っていることは広く知られている。\n\n日本のどの街にどんな音楽家や学者の像が立てられているだろうか。今日まで日本を支配してきた権力は、文化を理解する能力を持たなかった。人間の智慧がこしらえられるものは、①武器と牢獄とであり、人々の間に響く声といえば号令だとしか考えなかった。ましてや人民の精神的解放のために生涯を捧げた解放者の像などはあり得ない。\n\n明治末期から大正にかけて、日本のブルジョア・インテリゲンツィア（知識人層）の文学は、現実の暗黒と専制に直面して苦悩した。ただ現象ばかりを追っかけるリアリズムでは現実を芸術として再現することさえ不可能である。現実に囚われて自己の保身や権力への妥協に汲々としていては、真の芸術的昇華に辿り着けないからである。\n\n夏目漱石は、②多くの限界の見える作家であるが、明治の官僚主義や世俗の栄達を拒み、文部省の文学博士号授与をきっぱりと辞退した。彼は権力に媚びず、知識人の独立と個人の内面的尊厳を守り抜こうとした。その姿勢は、妥協を許さない作家の良心の証左である。芸術や学問の真の価値は、権力のお墨付きや世俗の栄誉にあるのではなく、人間性の尊厳のためにいかなる行動をとったかという「行為の価値」にあるのである。",
    "passageRuby": "オーストリアのウィーン市(し)のはずれに公園(こうえん)のように美(うつく)しい墓地(ぼち)がある。そこにベートーヴェンの墓(はか)や、モーツァルトの墓(はか)があった。偉大(いだい)な音楽家(おんがくか)の生涯(しょうがい)にふさわしく、心(こころ)をこめ意匠(いしょう)された墓(はか)が晩春(ばんしゅん)の花(はな)にかこまれているのを見(み)た。ポーランドのワルシャワ市(し)にはショパンの記念像(きねんぞう)があり、モスクワの街々(まちまち)にはプーシキンやゴーリキーら文学者(ぶんがくしゃ)の記念像(きねんぞう)が立(た)っていることは広(ひろ)く知(し)られている。<br><br>日本(にほん)のどの街(まち)にどんな音楽家(おんがくか)や学者(がくしゃ)の像(ぞう)が立(た)てられているだろうか。今日(こんにち)まで日本(にほん)を支配(しはい)してきた権力(けんりょく)は、文化(ぶんか)を理解(りかい)する能力(のうりょく)を持(も)たなかった。人間(にんげん)の智慧(ちえ)がこしらえられるものは、①<u>武器(ぶき)と牢獄(ろうごく)とであり、人々(ひとびと)の間(あいだ)に響(ひび)く声(こえ)といえば号令(ごうれい)だとしか考(かんが)えなかった</u>。ましてや人民(じんみん)の精神的解放(せいしんてきかいほう)のために生涯(しょうがい)を捧(ささ)げた解放者(かいほうしゃ)の像(ぞう)などはあり得(え)ない。<br><br>明治末期(めいじまっき)から大正(たいしょう)にかけて、日本(にほん)のブルジョア・インテリゲンツィア（知識人層(ちしきじんそう)）の文学(ぶんがく)は、現実(げんじつ)の暗黒(あんこく)と専制(せんせい)に直面(ちょくめん)して苦悩(くのう)した。ただ現象(げんしょう)ばかりを追(お)っかけるリアリズムでは現実(げんじつ)を芸術(げいじゅつ)として再現(さいげん)することさえ不可能(ふかのう)である。現実(げんじつ)に囚(とら)われて自己(じこ)の保身(ほしん)や権力(けんりょく)への妥協(だきょう)に汲々(きゅうきゅう)としていては、真(しん)の芸術的昇華(げいじゅつてきしょうか)に辿(たど)り着(つ)けないからである。<br><br>夏目漱石(なつめそうせき)は、②<u>多(おお)くの限界(げんかい)の見える作家(さっか)であるが</u>、明治(めいじ)の官僚主義(かんりょうしゅぎ)や世俗(せぞく)の栄達(えいだつ)を拒(こば)み、文部省(もんぶしょう)の文学博士号(ぶんがくはくしごう)授与(じゅよ)をきっぱりと辞退(じたい)した。彼(かれ)は権力(けんりょく)に媚(こ)びず、知識人(ちしきじん)の独立(どくりつ)と個人(こじん)の内面的尊厳(ないめんてきそんげん)を守(まも)り抜(ぬ)こうとした。その姿勢(しせい)は、妥協(だきょう)を許(ゆる)さない作家(さっか)の良心(りょうしん)の証左(しょうさ)である。芸術(げいじゅつ)や学問(がくもん)の真(しん)の価値(かち)は、権力(けんりょく)のお墨付(すみつ)きや世俗(せぞく)の栄誉(えいよ)にあるのではなく、人間性(にんげんせい)の尊厳(そんげん)のためにいかなる行動(こうどう)をとったかという「行為(こうい)の価値(かち)」にあるのである。",
    "passageTrans": "오스트리아 빈 시 외곽에 공원처럼 아름다운 묘지가 있다. 그곳에 베토벤의 묘와 모차르트의 묘가 있었다. 위대한 음악가의 생애에 걸맞게 정성을 다해 고안된 묘가 늦봄의 꽃에 둘러싸여 있는 것을 보았다. 폴란드 바르샤바 시에는 쇼팽의 기념상이 있고, 모스크바 거리 곳곳에는 푸시킨이나 고리키 등 문학자들의 기념상이 서 있는 것은 널리 알려져 있다.\n\n일본의 어느 거리에 어떤 음악가나 학자의 동상이 세워져 있는가. 오늘날까지 일본을 지배해 온 권력은 문화를 이해하는 능력을 갖지 못했다. 인간의 지혜가 만들어내는 것은 ①무기와 감옥뿐이며, 사람들 사이에 울려 퍼지는 소리라고는 호령뿐이라고밖에 생각하지 않았다. 하물며 인민의 정신적 해방을 위해 생애를 바친 해방자의 동상 따위는 있을 수 없다.\n\n메이지 말기부터 다이쇼 시대에 걸쳐 일본 부르주아 인텔리겐치아(지식인층)의 문학은 현실의 암흑과 전제에 직면하여 고뇌했다. 단지 현상만을 쫓아가는 리얼리즘으로는 현실을 예술로서 재현하는 것조차 불가능하다. 현실에 사로잡혀 자기의 보신이나 권력으로의 타협에 급급해서는 진정한 예술적 승화에 도달할 수 없기 때문이다.\n\n나쓰메 소세키는 ②많은 한계가 보이는 작가이기는 하지만, 메이지의 관료주의나 세속의 영달을 거부하고 문부성의 문학박사 학위 수여를 단호히 사퇴했다. 그는 권력에 아첨하지 않고 지식인의 독립과 개인의 내면적 존엄을 지켜내려 했다. 그 자세는 타협을 용납하지 않는 작가 양심의 증거이다. 예술과 학문의 진정한 가치는 권력의 공인이나 세속의 영화에 있는 것이 아니라, 인간성의 존엄을 위해 어떠한 행동을 취했는가 하는 '행위의 가치'에 있는 것이다.",
