    "passagePlain": "デジタルやアナログという言葉は、本来は情報工学や電子技術の専門用語であった。しかし今日では、人間の性格や思考様式、あるいは人間関係や文化的表現を形容するような用法に[06]、本来の技術用語の枠を超えたさまざまな意味やイメージをまとって広く使用されている。技術用語の枠を超えた用法では、デジタルやアナログという言葉が漠然としたイメージで使用されているため、これらの意味にはさまざまな混乱や誤解も含まれている。デジタルとアナログの本来の技術的な意味を正確に理解[07]、そのような混乱が解消できるかといえば、[08]単純なことではない。\n\n明確な定義の範囲で使用される言葉の範囲を超えてしまうような言葉の意味は、高度に発展と変容を続ける情報社会にあって、それが使用される社会的現実を鋭敏に反映するものとなっている。明確な技術用語であったはずのデジタルとアナログという語の意味は、その意味が拡散したり曖昧になっているだけでなく、時には反転したり融合したりさえしているような現象もしばしば見受けられる。\n\n本章では具体的にデジタルとアナログという言葉がどのようなイメージで使用されているかを分析する[09]、現在の情報社会を形成している根幹の情報や技術というものを、私たちがどのような感覚やイメージで受容しているかを考察していく。[10]、デジタルの概念が情報社会の中でどのように機能し、どのような方向を目指して進化しているのかを見極めていく。",
    "passageRuby": "デジタルやアナログという言葉(ことば)は、本来(ほんらい)は情報工学(じょうほうこうがく)や電子技術(でんしぎじゅつ)の専門用語(せんもんようご)であった。しかし今日(こんにち)では、人間(にんげん)の性格(せいかく)や思考様式(しこうようしき)、あるいは人間関係(にんげんかんけい)や文化的表現(ぶんかてきひょうげん)を形容(けいよう)するような用法(ようほう)に[06]、本来(ほんらい)の技術用語(ぎじゅつようご)の枠(わく)を超(こ)えたさまざまな意味(いみ)やイメージをまとって広(ひろ)く使用(しよう)されている。技術用語(ぎじゅつようご)の枠(わく)を超(こ)えた用法(ようほう)では、デジタルやアナログという言葉(ことば)が漠然(ばくぜん)としたイメージで使用(しよう)されているため、これらの意味(いみ)にはさまざまな混乱(こんらん)や誤解(ごかい)も含(ふく)まれている。デジタルとアナログの本来(ほんらい)の技術的(ぎじゅつてき)な意味(いみ)を正確(せいかく)に理解(りかい)[07]、そのような混乱(こんらん)が解消(かいしょう)できるかといえば、[08]単純(たんじゅん)なことではない。<br><br>明確(めいかく)な定義(ていぎ)の範囲(はんい)で使用(しよう)される言葉(ことば)の範囲(はんい)を超(こ)えてしまうような言葉(ことば)の意味(いみ)は、高度(こうど)に発展(はってん)と変容(へんよう)を続(つづ)ける情報社会(じょうほうしゃかい)にあって、それが使用(しよう)される社会的現実(しゃかいてきげんじつ)を鋭敏(えいびん)に反映(はんえい)するものとなっている。明確(めいかく)な技術用語(ぎじゅつようご)であったはずのデジタルとアナログという語(ご)の意味(いみ)は、その意味(いみ)が拡散(かくさん)したり曖昧(あいまい)になっているだけでなく、時(とき)には反転(はんてん)したり融合(ゆうごう)したりさえしているような現象(げんしょう)もしばしば見受(みう)けられる。<br><br>本章(ほんしょう)では具体的(ぐたいてき)にデジタルとアナログという言葉(ことば)がどのようなイメージで使用(しよう)されているかを分析(ぶんせき)する[09]、現在(げんざい)の情報社会(じょうほうしゃかい)を形成(けいせい)している根幹(こんかん)の情報(じょうほう)や技術(ぎじゅつ)というものを、私(わたし)たちがどのような感覚(かんかく)やイメージで受容(じゅよう)しているかを考察(こうさつ)していく。[10]、デジタルの概念(がいねん)が情報社会(じょうほうしゃかい)の中(なか)でどのように機能(きのう)し、どのような方向(ほうこう)を目指(めざ)して進化(しんか)しているのかを見極(みきわ)めていく。",
    "passageTrans": "디지털이나 아날로그라는 말은 본래 정보공학이나 전자 기술의 전문 용어였다. 그러나 오늘날에는 인간의 성격이나 사고방식, 혹은 인간관계나 문화적 표현을 형용하는 용법으로 [06: 보이듯이], 본래의 기술 용어의 틀을 넘어선 다양한 의미와 이미지를 띠며 널리 사용되고 있다. 기술 용어의 틀을 넘어선 용법에서는 디지털이나 아날로그라는 말이 막연한 이미지로 사용되고 있기 때문에 이러한 의미에는 다양한 혼란이나 오해도 포함되어 있다. 디지털과 아날로그의 본래 기술적 의미를 정확하게 이해[07: 하기만 하면], 그러한 혼란이 해소될 수 있는가 하면 [08: 그리] 단순한 문제가 아니다.\n\n명확한 정의의 범위를 넘어버리는 말의 의미는 고도로 발전과 변용을 거듭하는 정보사회에 있어서 그것이 사용되는 사회적 현실을 예민하게 반영하는 것이 되고 있다. 명확한 기술 용어였던 디지털과 아날로그라는 말의 의미는 확산되거나 애매해지고 있을 뿐만 아니라 때로는 반전되거나 융합되기까지 하는 현상도 자주 목격된다.\n\n본 장에서는 구체적으로 디지털과 아날로그라는 말이 어떠한 이미지로 사용되고 있는가를 분석하는 [09: 일을 통해], 현재의 정보사회를 형성하고 있는 근간의 정보와 기술이라는 것을 우리가 어떤 감각과 이미지로 수용하고 있는가를 고찰해 나갈 것이다. [10: 그리고], 디지털의 개념이 정보사회 속에서 어떻게 기능하고 어떤 방향을 지향하며 진화하고 있는가를 규명해 나갈 것이다.",
