    "passagePlain": "私に親しいある老科学者が、ある日私に次のようなことを[16]。「科学者になるには『あたま』がよくなくてはいけない」これは普通世人の口にする一つの命題である。これはある意味ではほんとうだと思われる。しかし、一方でまた「科学者はあたまが[17]」という命題も、ある意味ではやはりほんとうである。そうしてこの後のほうの命題は、それを指摘し解説する人が比較的少数である。\n\nこの一見相反する二つの命題は、実は一つのものの互いに対立し共存する二つの半面を表現するものである。この見かけ上の[18]は、実は「あたま」という言葉の内容に関する定義の曖昧不鮮明から生まれることはもちろんである。\n\n論理の連鎖のただ一つの輪をも取り失わないように、また混乱の中に部分と全体との関係を見失わないようにするためには、正確でかつ緻密な頭脳を要する。紛糾した可能性の岐路に立ったときに、取るべき道を誤らないためには前途を見透す内察と直観の力を持たなければならない。[19]、この意味ではたしかに科学者は「あたま」が[20]。\n\nしかしまた、普通にいわれる常識的にわかりきったと思われることで、そうして普通の意味でいわゆるあたまの悪い人にでも容易にわかったと思われるような日常茶飯事の中に、何かしら不可解な疑点を認め、その闡明に苦吟するということが、科学的研究に従事する者にはさらにいっそう重要必須なことである。この点で科学者は、普通の頭の悪い人よりも、もっともっと物わかりの悪いの呑み込みの悪い田舎者であり朴念仁でなければならない。",
    "passageRuby": "私(わたし)に親(した)しいある老科学者(ろうかがくしゃ)が、ある日(ひ)私(わたし)に次(つぎ)のようなことを[16]。「科学者(かがくしゃ)になるには『あたま』がよくなくてはいけない」これは普通(ふつう)世人(せじん)の口(くち)にする一(ひと)つの命題(めいだい)である。これはある意味(いみ)ではほんとうだと思(おも)われる。しかし、一方(いっぽう)でまた「科学者(かがくしゃ)はあたまが[17]」という命題(めいだい)も、ある意味(いみ)ではやはりほんとうである。そうしてこの後(のち)のほうの命題(めいだい)は、それを指摘(してき)し解説(かいせつ)する人(ひと)が比較的(ひかくてき)少数(しょうすう)である。<br><br>この一見(いっけん)相反(あいはん)する二(ふた)つの命題(めいだい)は、実(じつ)は一(ひと)つのものの互(たが)いに対立(たいりつ)し共存(きょうぞん)する二(ふた)つの半面(はんめん)を表現(ひょうげん)するものである。この見(み)かけ上(じょう)の[18]は、実(じつ)は「あたま」という言葉(ことば)の内容(ないよう)に関(かん)する定義(ていぎ)の曖昧不鮮明(あいまいふせんめい)から生(う)まれることはもちろんである。<br><br>論理(ろんり)の連鎖(れんさ)のただ一(ひと)つの輪(わ)をも取(と)り失(うしな)わないように、また混乱(こんらん)の中(なか)に部分(ぶぶん)と全体(ぜんたい)との関係(かんけい)を見失(みうしな)わないようにするためには、正確(せいかく)でかつ緻密(ちみつ)な頭脳(ずのう)を要(よう)する。紛糾(ふんきゅう)した可能性(かのうせい)の岐路(きろ)に立(た)ったときに、取(と)るべき道(みち)を誤(あやま)らないためには前途(ぜんと)を見透(みす)す内察(ないさつ)と直観(ちょっかん)の力(ちから)を持(も)たなければならない。[19]、この意味(いみ)ではたしかに科学者(かがくしゃ)は「あたま」が[20]。<br><br>しかしまた、普通(ふつう)にいわれる常識的(じょうしきてき)にわかりきったと思(おも)われることで、そうして普通(ふつう)の意味(いみ)でいわゆるあたまの悪(わる)い人(ひと)にでも容易(ようい)にわかったと思(おも)われるような日常茶飯事(にちじょうさはんじ)の中(なか)に、何(なに)かしら不可解(ふかかい)な疑点(ぎてん)を認(みと)め、その闡明(せんめい)に苦吟(くぎん)するということが、科学的研究(かがくてきけんきゅう)に従事(じゅうじ)する者(もの)にはさらにいっそう重要必須(じゅうようひっす)なことである。この点(てん)で科学者(かがくしゃ)は、普通(ふつう)の頭(あたま)の悪(わる)い人(ひと)よりも、もっともっと物(もの)わかりの悪(わる)いの呑(の)み込(こ)みの悪(わる)い田舎者(いなかもの)であり朴念仁(ぼくねんじん)でなければならない。",
    "passageTrans": "나와 친한 어느 원로 과학자가 어느 날 나에게 다음과 같은 이야기를 [16: 들려주었다]. '과학자가 되려면 머리가 좋지 않으면 안 된다.' 이것은 보통 세상 사람들이 입에 담는 하나의 명제이다. 이것은 어떤 의미에서는 사실이라고 생각된다. 그러나 다른 한편으로 또 '과학자는 머리가 [17: 나쁘지 않으면 안 된다]'라는 명제도 어떤 의미에서는 역시 사실이다. 그리고 이 뒤쪽의 명제는 그것을 지적하고 해설하는 사람이 비교적 소수이다.\n\n이 언뜻 상반되는 두 명제는 실은 한 사물의 서로 대립하면서 공존하는 두 반면을 표현하는 것이다. 이 겉보기상의 [18: 역설(패러독스)]은 실은 '머리'라는 말의 내용에 관한 정의의 애매함과 불선명함에서 생겨나는 것임은 물론이다.\n\n논리의 사슬 중 단 하나의 고리도 놓치지 않도록, 또 혼란 속에서 부분과 전체의 관계를 놓치지 않도록 하기 위해서는 정확하고도 치밀한 두뇌를 요한다. 뒤얽힌 가능성의 기로에 섰을 때 취해야 할 길을 그르치지 않기 위해서는 앞길을 꿰뚫어 보는 통찰과 직관의 힘을 가져야 한다. [19: 그러므로], 이런 의미에서는 분명 과학자는 '머리'가 [20: 좋지 않으면 안 되는] 것이다.\n\n그러나 또 보통 상식적으로 뻔하다고 여겨지는 일에서, 보통 의미로 머리가 나쁜 사람에게조차 쉽게 이해되었다고 생각될 법한 일상다반사 속에서 무언가 불가해한 의문점을 발견하고 그 규명에 고뇌한다는 것이 과학적 연구에 종사하는 자에게는 더욱더 중요하고 필수적인 일이다. 이런 점에서 과학자는 보통의 머리 나쁜 사람보다도 훨씬 더 말귀를 못 알아듣고 이해가 더딘 촌뜨기이자 고지식한 사람이어야만 한다.",
