    "wordCount": 910,
    "estimatedMinutes": 9,
    "passagePlain": "一見閑静な田舎に住まっていては、とても一生懸命な自分の仕事に没頭しているわけにはいかない。田舎では人間関係があまりに濃密で、誰がいつ何をしているかという相互監視のような視線から逃れられないからである。それに引き換え、都会のいわゆる①「人間砂漠」の中が一番都合がいい。都会の満員電車の中では、隣り合って立っている人間同士がお互いに無関心であり、他人の一挙手一投足に干渉してこない。この絶対的な他者性の海の中にこそ、精神的な自由と孤独な創造の時間を見出すことができるのである。\n\n世人はよく、田舎の自然の豊かさや人情の温かさを賛美し、都会の無機質さと冷淡さを嘆く。しかし、それは一面的な見方にすぎない。人間関係の煩わしさから解放され、自己の内面と深く対話するためには、他人の視線から完全に遮断された匿名性が必要不可欠である。\n\n都会という砂漠に身を置くことで初めて、人間は他者に煩わされることなく、真に自己の使命や研究に専념할 수 있는 것이다.",
    "passageRuby": "一見(いっけん)閑静(かんせい)な田舎(いなか)に住(す)まっていては、とても一生懸命(いっしょうけんめい)な自分(じぶん)の仕事(しごと)に没頭(ぼっとう)しているわけにはいかない。田舎(いなか)では人間関係(にんげんかんけい)があまりに濃密(のうみつ)で、誰(だれ)がいつ何(なに)をしているかという相互監視(そうごかんし)のような視線(しせん)から逃(nog)れられないからである。それに引(ひ)き換(か)え、都会(とかい)のいわゆる①「<u>人間砂漠(にんげんさばく)</u>」の中(なか)が一番(いちばん)都合(つごう)がいい。都会(とかい)の満員電車(まんいんでんしゃ)の中(なか)では、隣(とな)り合(あ)って立(た)っている人間同士(にんげんどうし)がお互(たが)いに無関心(むかんしん)であり、他人(たにん)の一挙手一投足(いっきょしゅいっとうそく)に干渉(かんしょう)してこない。この絶対的(ぜったいてき)な他者性(たしゃせい)の海(うみ)の中(なか)にこそ、精神的(せいしんてき)な自由(じゆう)と孤独(こどく)な創造(そうぞう)の時間(じかん)を見出(みいだ)すことができるのである。<br><br>世人(せじん)はよく、田舎(いなか)の自然(しぜん)の豊(ゆた)かさや人情(にんじょう)の温(あたた)かさを賛美(さんび)し、都会(とかい)の無機質(むきしつ)さと冷淡(れいたん)さを嘆(なげ)く。しかし、それは面的(めんてき)な見方(みかた)にすぎない。人間関係(にんげんかんけい)の煩(わずら)わしさから解放(かいほう)され、自己(じこ)の内面(ないめん)と深(ふか)く対話(たいわ)するためには、他人(たにん)の視線(しせん)から完全(かんぜん)に遮断(しゃだん)された匿名性(とくめいせい)が必要不可欠(ひつようふかけつ)である。<br><br>都会(とかい)という砂漠(さばく)に身(み)を置(お)くことで初(はじ)めて、人間(にんげん)は他者(たしゃ)に煩(わずら)わされることなく、真(しん)に自己(じこ)の使命(しめい)や研究(けんきゅう)に専念(せんねん)できるのである。",
    "passageTrans": "얼핏 한적해 보이는 시골에 살아서는 도저히 온 힘을 다해 자신의 일에 몰두하고 있을 수가 없다. 시골에서는 인간관계가 너무나 농밀하여 누가 언제 무엇을 하고 있는가 하는 상호 감시와 같은 시선에서 벗어날 수 없기 때문이다. 그에 반해 도시의 이른바 ①'인간사막' 속이 가장 형편이 좋다. 도시의 만원 전철 속에서는 이웃하여 서 있는 사람들끼리 서로 무관심하며 타인의 일거수일투족에 간섭해 오지 않는다. 이 절대적인 타자성의 바다 속에서야말로 정신적인 자유와 고독한 창조의 시간을 찾아낼 수 있는 것이다.\n\n세상 사람들은 흔히 시골의 풍요로운 자연이나 따뜻한 인정을 찬미하고 도시의 무기질함과 냉담함을 한탄한다. 그러나 그것은 일면적인 견해에 불과하다. 인간관계의 번거로움에서 해방되어 자신의 내면과 깊이 대화하기 위해서는 타인의 시선에서 완전히 차단된 익명성이 필요불가결하다.\n\n도시라는 사막에 몸을 둠으로써 비로소 인간은 타인에게 방해받지 않고 진정으로 자신의 사명이나 연구에 전념할 수 있는 것이다.",
