    "passagePlain": "[文章A]\n私の周囲でも夫婦別姓制度をどうしても導入したいと主張する人は殆どいません。しかし、実はそれを公表してしまうと少数派扱いされ、批判されるのを恐れて口を閉ざしている人が多いのです。特に研究者や専門職の女性にとって、結婚によって改姓することは、それまで築いてきた業績やキャリアの断絶を意味します。通称使用には限界があり、法的な選択的夫婦別姓制度の導入こそが、個人の尊厳と職業的継続性を保障する現実的な解決策です。\n\n[文章B]\n夫婦別姓制度の議論に対しては、家族の一体感や子供への影響を懸念する声が根強く存在します。同じ姓を名乗ることで家族としての絆が深まり、社会的な安定がもたらされるという考え方は、日本の伝統的な家族観に深く根ざしています。制度の改変を性急に進めるのではなく、多様な国民の合意形成を慎重に図る必要があります。",
    "passageRuby": "[文章A]<br>私(わたし)の周囲(しゅうい)でも夫婦別姓制度(ふうふべっせいせいど)をどうしても導入(どうにゅう)したいと主張(しゅちょう)する人(ひと)は殆(ほとん)どいません。しかし、実(じつ)はそれを公表(こうひょう)してしまうと少数派扱(しょうすうはあつか)いされ、批判(ひはん)されるのを恐(おそ)れて口(くち)を閉(と)ざしている人(ひと)が多(おお)いのです。特(とく)に研究者(けんきゅうしゃ)や専門職(せんもんしょく)の女性(じょせい)にとって、結婚(けっこん)によって改姓(かいせい)することは、それまで築(きず)いてきた業績(ぎょうせき)やキャリア(きゃりあ)の断絶(だんぜつ)を意味(いみ)します。通称使用(つうしょうしよう)には限界(げんかい)があり、法的(ほうてき)な選択的夫婦別姓制度(せんたくてきふうふべっせいせいど)の導入(どうにゅう)こそが、個人(こじん)の尊厳(そんげん)と職業的継続性(しょくぎょうてきけいぞくせい)を保障(ほしょう)する現実的(げんじつてき)な解決策(かいけつさく)です。<br><br>[文章B]<br>夫婦別姓制度(ふうふべっせいせいど)の議論(ぎろん)に対(たい)しては、家族(かぞく)の一体感(いったいかん)や子供(こども)への影響(えいきょう)を懸念(けねん)する声(こえ)が根強(ねづよ)く存在(そんざい)します。同(おな)じ姓(せい)を名乗(なの)ることで家族(かぞく)としての絆(きずな)が深(ふか)まり、社会的(しゃかいてき)な安定(あんてい)がもたらされるという考(かんが)え方(かた)は、日本(にほん)の伝統的(でんとうてき)な家族観(かぞくかん)に深(ふか)く根(ね)ざしています。制度(せいど)の改変(かいへん)を性急(せいきゅう)に進(すす)めるのではなく、多様(たよう)な国民(こくみん)の合意形成(ごういけいせい)を慎重(しんちょう)に図(はか)る必要(ひつよう)があります。",
    "passageTrans": "[문장 A]\n내 주위에서도 부부별성 제도를 어떻게 해서든 도입하고 싶다고 주장하는 사람은 거의 없습니다. 그러나 실은 그것을 공표해 버리면 소수파 취급을 받아 비판받을 것을 두려워하여 입을 다물고 있는 사람이 많은 것입니다. 특히 연구자나 전문직 여성에게 있어 결혼으로 성을 바꾸는 것은 그때까지 쌓아 올린 업적이나 경력의 단절을 의미합니다. 통칭 사용에는 한계가 있으며, 법적인 선택적 부부별성 제도의 도입이야말로 개인의 존엄과 직업적 연속성을 보장하는 현실적인 해결책입니다.\n\n[문장 B]\n부부별성 제도의 논의에 대해서는 가족의 일체감이나 자녀에게 미치는 영향을 우려하는 목소리가 뿌리 깊게 존재합니다. 같은 성을 씀으로써 가족으로서의 유대가 깊어지고 사회적 안정이 가져다진다는 사고방식은 일본의 전통적인 가족관에 깊이 뿌리박혀 있습니다. 제도의 개변을 성급하게 추진할 것이 아니라 다양한 국민의 합의 형성을 신중하게 도모할 필요가 있습니다.",
