    "wordCount": 750,
    "estimatedMinutes": 5,
    "passagePlain": "【文部科学省 調査結果の概要】\n本年度における高校卒業者（中等教育学校後期課程修了者を含む）の「現役進学率」は過去最高の54.4%に達した。\n\n大学・短期大学（通信教育部等を含む）への進学総者数は約58万2千人（前年度より約8千人増加）となった。男女別に見ると、男子の現役進学率は52.8%、女子は56.0%となり、いずれも過去最高を更新した。\n\n都道府県別の現役進学率を見ると、最も高いのは京都府の67.0%であり、次いで東京都が65.3%、神奈川県が61.7%となっている。一方、前年度からの「進学率の上昇幅」が最も顕著であったのは島根県（+2.3ポイント）であり、次いで秋田県（+2.0ポイント）、宮城県（+1.6ポイント）であった。\n\n[表：主な都道府県の現役進学率および上昇幅]\n・京都府：進学率 67.0% (前年比 +0.8ポイント)\n・東京都：進学率 65.3% (前年比 +0.3ポイント)\n・神奈川県：進学率 61.7% (前年比 +0.5ポイント)\n・大阪府：進学率 59.2% (前年比 -0.2ポイント)\n・島根県：進学率 52.4% (前年比 +2.3ポイント)\n・秋田県：進学率 51.0% (前年比 +2.0ポイント)",
    "passageRuby": "【文部科学省(もんぶかがくしょう) 調査結果(ちょうさけっか)の概要(がいよう)】<br>本年度(ほんねんど)における高校卒業者(こうこうそつぎょうしゃ)の「現役進学率(げんえきしんがくりつ)」は過去最高(かこさいこう)の54.4%に達(たっ)した。<br><br>大学(だいがく)・短期大学(たんきだいがく)への進学総者数(しんがくそうしゃすう)は約(やく)58万(まん)2千人(せんにん)（前年度(ぜんねんど)より約(やく)8千人(せんにん)増加(ぞうか)）となった。男女別(だんじょべつ)に見(み)ると、男子(だんし)の現役進学率(げんえきしんがくりつ)は52.8%、女子(じょし)は56.0%となり、いずれも過去最高(かこさいこう)を更新(こうしん)した。<br><br>都道府県別(とどうふけんべつ)の現役進学率(げんえきしんがくりつ)を見(み)ると、最(もっと)も高(たか)いのは京都府(きょうとふ)の67.0%であり、次(つ)いで東京都(とうきょうと)が65.3%、神奈川県(かながわけん)が61.7%となっている。一方(いっぽう)、前年度(ぜんねんど)からの「進学率(しんがくりつ)の上昇幅(じょうしょうはば)」が最(もっと)も顕著(けんちょ)であったのは島根県(しまねけん)（+2.3ポイント）であり、次(つ)いで秋田県(あきたけん)（+2.0ポイント）、宮城県(みやぎけん)（+1.6ポイント）であった。<br><br>[表(ひょう)：主(おも)な都道府県(とどうふけん)の現役進学率(げんえきしんがくりつ)および上昇幅(じょうしょうはば)]<br>・京都府(きょうとふ)：進学率(しんがくりつ) 67.0% (前年比(ぜんねんひ) +0.8ポイント)<br>・東京都(とうきょうと)：進学率(しんがくりつ) 65.3% (前年比(ぜんねんひ) +0.3ポイント)<br>・神奈川県(かながわけん)：進学率(しんがくりつ) 61.7% (前年比(ぜんねんひ) +0.5ポイント)<br>・大阪府(おおさかふ)：進学率(しんがくりつ) 59.2% (前年比(ぜんねんひ) -0.2ポイント)<br>・島根県(しまねけん)：進学率(しんがくりつ) 52.4% (前年比(ぜんねんひ) +2.3ポイント)<br>・秋田県(あきたけん)：進学率(しんがくりつ) 51.0% (前年比(ぜんねんひ) +2.0ポイント)",
    "passageTrans": "【문부과학성 조사 결과 개요】\n금년도 고교 졸업자(중등교육학교 후기과정 수료자 포함)의 '현역 진학률'은 과거 최고인 54.4%에 달했다.\n\n대학·단기대학(통신교육부 등 포함)으로의 총 진학자 수는 약 58만 2천 명(전년도 대비 약 8천 명 증가)이 되었다. 남녀별로 보면 남자의 현역 진학률은 52.8%, 여자는 56.0%로 둘 다 과거 최고치를 경신했다.\n\n도도부현별 현역 진학률을 보면 가장 높은 곳은 교토부의 67.0%이며, 그다음이 도쿄도 65.3%, 가나가와현 61.7%로 이어진다. 한편 전년도 대비 '진학률 상승 폭'이 가장 현저했던 곳은 시마네현(+2.3%p)이었으며, 그다음이 아키타현(+2.0%p), 미야기현(+1.6%p)이었다.\n\n[표: 주요 도도부현의 현역 진학률 및 상승 폭]\n· 교토부: 진학률 67.0% (전년 대비 +0.8%p)\n· 도쿄도: 진학률 65.3% (전년 대비 +0.3%p)\n· 가나가와현: 진학률 61.7% (전년 대비 +0.5%p)\n· 오사카부: 진학률 59.2% (전년 대비 -0.2%p)\n· 시마네현: 진학률 52.4% (전년 대비 +2.3%p)\n· 아키타현: 진학률 51.0% (전년 대비 +2.0%p)",
