    "title": "미도리시 국제교류센터 일본어 교실 수강생 모집 안내",
    "wordCount": 420,
    "estimatedMinutes": 5,
    "passagePlain": "【みどり市国際交流センター　春期にほんご教室のご案内】\n\nみどり市にお住まい、または通勤・通学されている外国籍の方を対象に、実践的な日本語教室を開講します。\n\n◆ コース案内\n1. 入門クラス（火・金 10:00〜11:30）\n   - 対象：ひらがな・カタカナから学びたい方\n   - 定員：15名（先着順）\n2. 初級会話クラス（水 18:30〜20:00）\n   - 対象：日常生活での簡単な挨拶や買い物の会話ができる方\n   - 定員：20名\n3. ビジネス日本語クラス（土 14:00〜16:00）\n   - 対象：JLPT N3以上相当、または日本での就労を目指す方\n   - 定員：15名（※事前レベルチェック面談あり）\n\n◆ 受講料\n・入門・初級クラス：無料（テキスト代実費：2,000円）\n・ビジネス日本語クラス：5,000円（全10回、教材費込み）\n\n◆ 申込期間・方法\n・申込期間：3月1日（金）〜3月20日（水）必着\n・申込方法：当センターのウェブサイト専用フォーム、または窓口にて申請書を提出。\n※定員になり次第締め切ります。ビジネス日本語クラスの面談は3月23日（土）に実施します。\n※託児サービス（未就学児対象・1回300円）は火・金午前の入門クラスのみ利用可能です（要事前予約）。",
    "passageRuby": "【みどり市国際交流(こくさいこうりゅう)センター　春期(しゅんき)にほんご教室(きょうしつ)のご案内(あんない)】\n\nみどり市(し)にお住(す)まい、または通勤(つうきん)・通学(つうがく)されている外国籍(がいこくせき)の方(かた)を対象(たいしょう)に、実践的(じっせんてき)な日本語教室(にほんごきょうしつ)を開講(かいこう)します。\n\n◆ コース案内(あんない)\n1. 入門(にゅうもん)クラス（火(か)・金(きん) 10:00〜11:30）\n   - 対象(たいしょう)：ひらがな・カタカナから学(まな)びたい方(かた)\n   - 定員(ていいん)：15名(めい)（先着順(せんちゃくじゅん)）\n2. 初級会話(しょきゅうかいわ)クラス（水(すい) 18:30〜20:00）\n   - 対象(たいしょう)：日常生活(にちじょうせいかつ)での簡単(かんたん)な挨拶(あいさつ)や買(か)い物(もの)の会話(かいわ)ができる方(かた)\n   - 定員(ていいん)：20名(めい)\n3. ビジネス日本語(にほんご)クラス（土(ど) 14:00〜16:00）\n   - 対象(たいしょう)：JLPT N3以上相当(いじょうそうとう)、または日本(にほん)での就労(しゅうろう)を目指(めざ)す方(かた)\n   - 定員(ていいん)：15名(めい)（※事前(じぜん)レベルチェック面談(めんだん)あり）\n\n◆ 受講料(じゅこうりょう)\n・入門(にゅうもん)・初級(しょきゅう)クラス：無料(むりょう)（テキスト代実費(だいじっぴ)：2,000円(えん)）\n・ビジネス日本語(にほんご)クラス：5,000円(えん)（全(ぜん)10回(かい)、教材費込(きょうざいひこ)み）\n\n◆ 申込期間(もうしこみきかん)・方法(ほうほう)\n・申込期間(もうしこみきかん)：3月(がつ)1日(ついたち)（金(きん)）〜3月(がつ)20日(はつか)（水(すい)）必着(ひっちゃく)\n・申込方法(もうしこみほうほう)：当(とう)センターのウェブサイト専用(せんよう)フォーム、または窓口(まどぐち)にて申請書(しんせいしょ)を提出(ていしゅつ)。\n※定員(ていいん)になり次第(しだい)締(し)め切(き)ります。ビジネス日本語(にほんご)クラスの面談(めんだん)は3月(がつ)23日(にち)（土(ど)）に実施(じっし)します。\n※託児(たくじ)サービス（未就学児対象(みしゅうがくじたいしょう)・1回(かい)300円(えん)）は火(か)・金午前(きんごぜん)の入門(にゅうもん)クラスのみ利用可能(りようかのう)です（要事前予約(ようじぜんよやく)）。",
    "passageTrans": "【미도리시 국제교류센터 봄 학기 일본어 교실 안내】\n\n미도리시에 거주하시거나 통근·통학하는 외국 국적자를 대상으로 실천적인 일본어 교실을 개강합니다.\n\n◆ 코스 안내\n1. 입문 클래스 (화·금 10:00~11:30)\n   - 대상: 히라가나·가타카나부터 배우고 싶은 분\n   - 정원: 15명 (선착순)\n2. 초급 회화 클래스 (수 18:30~20:00)\n   - 대상: 일상생활의 간단한 인사나 쇼핑 대화가 가능한 분\n   - 정원: 20명\n3. 비즈니스 일본어 클래스 (토 14:00~16:00)\n   - 대상: JLPT N3 이상 상당 또는 일본 취업을 목표로 하는 분\n   - 정원: 15명 (※사전 레벨 체크 면담 있음)\n\n◆ 수강료\n- 입문·초급 클래스: 무료 (교재비 실비: 2,000엔)\n- 비즈니스 일본어 클래스: 5,000엔 (총 10회, 교재비 포함)\n\n◆ 신청 기간 및 방법\n- 신청 기간: 3월 1일(금) ~ 3월 20일(수) 필착\n- 신청 방법: 센터 웹사이트 전용 폼 또는 창구에서 신청서 제출.\n※정원이 차는 대로 마감합니다. 비즈니스 일본어 클래스 면담은 3월 23일(토)에 실시합니다.\n※탁아 서비스(미취학 아동 대상, 1회 300엔)는 화·금 오전 입문 클래스에서만 이용 가능합니다(사전 예약 필수).",
