    "passagePlain": "ボランティア活動助成金申請要項\n緑川大学では、国内各地でボランティア活動に参加する学生に対して、費用の一部を助成する制度を設けています。\n\n1. 助成対象者\n　緑川大学の学部生と大学院生\n\n2. 助成対象となる活動\n　公的団体が主催するボランティア活動\n\n3. 助成対象となる費用、助成が受けられる金額と回数\n　(1) 費用：ボランティア活動のために支出される交通費と宿泊費\n　(2) 金額\n　　・交通費：1回の活動につき、10,000円を上限として実費を支給します。\n　　・宿泊費：1回の活動につき、1泊あたり6,000円を上限として実費を支給します。2泊分までを支給対象とします。\n　(3) 回数：年度中2回まで\n\n4. 申請方法（A〜Cの書類の様式はホームページからダウンロード可）\n　活動終了後2か月以内に以下の書類をボランティアセンターに提出してください。\n　ただし、年度内最終提出期限は3月24日（厳守）とします。\n　　A：ボランティア活動助成金申請書\n　　B：ボランティア活動助成金振込口座届\n　　C：ボランティア活動証明書（受け入れ先の様式も可）\n　　D：領収書 ※\n　※宿泊費の領収書は必ず提出してください。交通費の領収書は入手が可能な場合は提出してください。交通費の領収書が入手できない場合は、実際にかかった金額をAに記入してください。\n\n5. 助成金振込\n　審査を行い、申請が認められた場合は、書類提出があった翌月の月末に振り込みます（書類に不備があった場合、振り込みが遅れる場合があります）。\n\n6. その他\n　「A：ボランティア活動助成金申請書」の「活動に参加した感想」をボランティアセンターのホームページで紹介することがあります。",
    "passageRuby": "ボランティア活動(かつどう)助成金(じょせいきん)申請(しんせい)要項(ようこう)\n緑川(みどりかわ)大学(だいがく)では、国内(こくない)各地(かくち)でボランティア活動(かつどう)に参加(さんか)する学生(がくせい)に対(たい)して、費用(ひよう)の一部(いちぶ)を助成(じょせい)する制度(せいど)を設(もう)けています。\n\n1. 助成(じょせい)対象者(たいしょうしゃ)\n　緑川(みどりかわ)大学(だいがく)の学部生(がくぶせい)と大学院生(だいがくいんせい)\n\n2. 助成(じょせい)対象(たいしょう)となる活動(かつどう)\n　公的(こうてき)団体(だんたい)が主催(しゅさい)するボランティア活動(かつどう)\n\n3. 助成(じょせい)対象(たいしょう)となる費用(ひよう)、助成(じょせい)が受(う)けられる金額(きんがく)と回数(かいすう)\n　(1) 費用(ひよう)：ボランティア活動(かつどう)のために支出(ししゅつ)される交通費(こうつうひ)と宿泊費(しゅくはくひ)\n　(2) 金額(きんがく)\n　　・交通費(こうつうひ)：1回(かい)の活動(かつどう)につき、10,000円(えん)を上限(じょうげん)として実費(じっぴ)を支給(しきゅう)します。\n　　・宿泊費(しゅくはくひ)：1回(かい)の活動(かつどう)につき、1泊(ぱく)あたり6,000円(えん)を上限(じょうげん)として実費(じっぴ)を支給(しきゅう)します。2泊分(はくぶん)までを支給(しきゅう)対象(たいしょう)とします。\n　(3) 回数(かいすう)：年度中(ねんどちゅう)2回(かい)まで\n\n4. 申請(しんせい)方法(ほうほう)（A〜Cの書類(しょるい)の様式(ようしき)はホームページからダウンロード可(か)）\n　活動(かつどう)終了後(しゅうりょうご)2か月以内(いない)に以下(いか)の書類(しょるい)をボランティアセンターに提出(ていしゅつ)してください。\n　ただし、年度内(ねんどない)最終(さいしゅう)提出(ていしゅつ)期限(きげん)は3月(がつ)24日(にち)（厳守(げんしゅ)）とします。\n　　A：ボランティア活動(かつどう)助成金(じょせいきん)申請書(しんせいしょ)\n　　B：ボランティア活動(かつどう)助成金(じょせいきん)振込(ふりこみ)口座届(こうざとどけ)\n　　C：ボランティア活動(かつどう)証明書(しょうめいしょ)（受(う)け入(い)れ先(さき)の様式(ようしき)も可(か)）\n　　D：領収書(りょうしゅうしょ) ※\n　※宿泊費(しゅくはくひ)の領収書(りょうしゅうしょ)は必(かなら)ず提出(ていしゅつ)してください。交通費(こうつうひ)の領収書(りょうしゅうしょ)は入手(にゅうしゅ)が可能(かのう)な場合(ばあい)は提出(ていしゅつ)してください。交通費(こうつうひ)の領収書(りょうしゅうしょ)が入手(にゅうしゅ)できない場合(ばあい)は、実際(じっさい)にかかった金額(きんがく)をAに記入(きにゅう)してください。\n\n5. 助成金(じょせいきん)振込(ふりこみ)\n　審査(しんさ)を行(おこな)い、申請(しんせい)が認(みと)められた場合(ばあい)は、書類(しょるい)提出(ていしゅつ)があった翌月(よくげつ)の月末(げつまつ)に振(ふ)り込(こ)みます（書類(しょるい)に不備(ふび)があった場合(ばあい)、振(ふ)り込(こ)みが遅(おく)れる場合(ばあい)があります）。\n\n6. その他(ほか)\n　「A：ボランティア活動(かつどう)助成金(じょせいきん)申請書(しんせいしょ)」の「活動(かつどう)に参加(さんか)した感想(かんそう)」をボランティアセンターのホームページで紹介(しょうかい)することがあります。",
    "passageTrans": "자원봉사 활동 조성금(지원금) 신청 요강\n미도리카와 대학에서는 국내 각지에서 자원봉사 활동에 참가하는 학생에게 비용의 일부를 지원하는 제도를 마련하고 있습니다.\n\n1. 지원 대상자\n　미도리카와 대학 학부생 및 대학원생\n2. 지원 대상 활동\n　공적 단체가 주최하는 자원봉사 활동\n3. 지원 대상 비용, 지원 금액 및 횟수\n　(1) 비용: 자원봉사 활동을 위해 지출되는 교통비와 숙박비\n　(2) 금액\n　　· 교통비: 1회 활동당 10,000엔을 상한으로 실비를 지급합니다.\n　　· 숙박비: 1회 활동당 1박당 6,000엔을 상한으로 실비를 지급합니다. 최대 2박분까지 지급 대상으로 합니다.\n　(3) 횟수: 연도 중 최대 2회까지\n4. 신청 방법 (A~C 서류 양식은 홈페이지에서 다운로드 가능)\n　활동 종료 후 2개월 이내에 아래 서류를 자원봉사 센터에 제출해 주십시오.\n　단, 연도 내 최종 제출 기한은 3월 24일(엄수)로 합니다.\n　　A: 자원봉사 활동 조성금 신청서\n　　B: 자원봉사 활동 조성금 입금 계좌 신고서\n　　C: 자원봉사 활동 증명서 (수용 기관 양식도 가능)\n　　D: 영수증 ※\n　※ 숙박비 영수증은 반드시 제출해 주십시오. 교통비 영수증은 입수가 가능한 경우 제출해 주십시오. 교통비 영수증을 입수할 수 없는 경우에는 실제로 든 금액을 A에 기입해 주십시오.\n5. 조성금 입금\n　심사를 거쳐 신청이 승인된 경우, 서류 제출 다음 달 말일에 입금합니다(서류 미비 시 입금이 지연될 수 있습니다).\n6. 기타\n　'A: 신청서'의 '활동 참가 소감'을 자원봉사 센터 홈페이지에 소개할 수 있습니다.",
