    "title": "가로수가 만드는 자연의 벽과 거리의 일체화 (並木の効果と街並みの一体化)",
    "source": "Nihonez N1 실전 (2020.12 단문 2)",
    "wordCount": 215,
    "estimatedMinutes": 3,
    "passagePlain": "並木は四季折々に変化する自然の壁である。葉を落として列柱のような状態にあったり、花を咲かせて賑やかなトンネル状の壁を作ったり、葉を繁らせて密な緑陰の壁になったりする。この連続した柔らかな透けた壁が、どれほど街並みの一体化に役立っているか。まとまりがなく不揃いな街路も、並木によってまとめられ、緩やかな連結を成功させている例など、数え上げればきりがないのである。\n\n(注1) 列柱：一列に並んだ柱\n(注2) 緑陰：木が繁ってできた日陰",
    "passageRuby": "並木(なみき)は四季折々(しきおりおり)に変化(へんか)する自然(しぜん)の壁(かべ)である。葉(は)を落(お)として列柱(れっちゅう)のような状態(じょうたい)にあったり、花(はな)を咲(さ)かせて賑(にぎ)やかなトンネル状(じょう)の壁(かべ)を作(つく)ったり、葉(は)を繁(しげ)らせて密(みつ)な緑陰(りょくいん)の壁(かべ)になったりする。<u>この連続(れんぞく)した柔(やわ)らかな透(す)けた壁(かべ)が、どれほど街並(まちな)みの一体化(いったいか)に役立(やくだ)っているか。まとまりがなく不揃(ふぞろ)いな街路(がいろ)も、並木(なみき)によってまとめられ、緩(ゆる)やかな連結(れんけつ)を成功(せいこう)させている</u>例(れい)など、数(かぞ)え上(あ)げればきりがないのである。\n\n(注1) 列柱(れっちゅう)：一列(いちれつ)に並(なら)んだ柱(はしら)\n(注2) 緑陰(りょくいん)：木(き)が繁(しげ)ってできた日陰(ひかげ)",
    "passageTrans": "가로수는 사계절 그때그때 변화하는 자연의 벽이다. 잎을 떨어뜨려 열주(주1)와 같은 상태로 있기도 하고, 꽃을 피워 활기찬 터널 모양의 벽을 만들기도 하며, 잎을 무성하게 피워 빽빽한 녹음(주2)의 벽이 되기도 한다. 이 연속된 부드럽고 비치는 벽이 얼마나 거리 풍경의 일체화에 도움이 되고 있는가. 통일성이 없고 제각각인 가로(거리)도 가로수에 의해 하나로 묶여 완만한 연결을 성공시키고 있는 사례 따위는 일일이 헤아리자면 끝이 없는 것이다.\n\n(주1) 열주: 한 줄로 늘어선 기둥\n(주2) 녹음: 나무가 우거져 생긴 그늘",
