    "wordCount": 205,
    "estimatedMinutes": 3,
    "passagePlain": "筆者がレコード会社の宣伝担当者から聞いた言葉に「流行っていると思わせれば、本当に流行る」というのがある。こうした宣伝の場面において音楽産業が力を注ぐのは「事実」ではなく「買い手にそう思わせること」、つまり「認識の形成」である。こうした手法を音楽産業は「夢を売る」とよく呼ぶ。つまり音楽産業は買い手がほしがる「ファンタジー」（注1）を先んじてキャッチし、商品化し、売ることに長けている。\n\n(注1) ファンタジー：幻想",
    "passageRuby": "筆者(ひっしゃ)がレコード会社(がいしゃ)の宣伝担当者(せんでんたんとうしゃ)から聞(き)いた言葉(ことば)に「流行(はや)っていると思(おも)わせれば、本当(ほんとう)に流行(はや)る」というのがある。<u>こうした宣伝(せんでん)の場面(ばめん)において音楽産業(おんがくさんぎょう)が力(ちから)を注(そそ)ぐのは「事実(じじつ)」ではなく「買(か)い手(て)にそう思(おも)わせること」、つまり「認識(にんしき)の形成(けいせい)」である</u>。こうした手法(しゅほう)を音楽産業(おんがくさんぎょう)は<u>「夢(ゆめ)を売(う)る」</u>とよく呼(よ)ぶ。つまり音楽産業(おんがくさんぎょう)は買(か)い手(て)がほしがる「ファンタジー」（注1）を先(さき)んじてキャッチし、商品化(しょうひんか)し、売(う)ることに長(た)けている。\n\n(注1) ファンタジー：幻想(げんそう)",
    "passageTrans": "필자가 레코드 회사의 홍보 담당자에게서 들은 말 중에 '유행하고 있다고 생각하게 만들면 정말로 유행한다'라는 말이 있다. 이러한 홍보 현장에서 음악 산업이 힘을 쏟는 것은 '사실'이 아니라 '구매자로 하여금 그렇게 생각하게 만드는 것', 즉 '인식의 형성'이다. 이러한 수법을 음악 산업은 흔히 '꿈을 판다'라고 부른다. 다시 말해 음악 산업은 구매자가 원하는 '판타지'(주1)를 한발 앞서 포착하여 상품화하고 판매하는 데 능숙하다.\n\n(주1) 판타지: 환상",
