    "passagePlain": "ある行動を何度も繰り返せば、それが自動化され、あまりそのことに思考を向けないようになっていくことが多いが、いつもそうなるとは限らない。例えば、人との雑談の中で、自分の考えを率直に述べるということをいつもやっていれば、確かにそのことは自動化され、自分の考えを述べようと特に意識しないでも、気楽に自分の考えを話すような習慣ができる。\nしかし、もし、率直に自分の考えを述べたときに、周囲の人から非難されたり、拒否されたりするということが繰り返されると、多くの場合、率直に話すことは自分にマイナスになるという考えが起こって、率直に話すという行動に自分でブレーキをかけるようになる。何回もブレーキをかけていると、ブレーキをかけること自体が自動化して、自分では行動の結果を取り立てて予期することなしに、なんとなく、率直に発言することが少なくなり、おとなしくなるといった変化が起こってくる。このような現象を行動の抑制の自動化という。\n行動の抑制の場合も、それが自動化すればするほど、思考の果たす役割は少なくなるのだが、思考の仕方や内容によって抑制の度合いは変わってくる。例えば、自分の述べようとする意見について、何回も繰り返し考えていると、だんだん抑制が弱まってきて、気楽に発言できるようになることもあり、逆に、考えれば考えるほど、発言後の嫌な予想と結びつき、抑制が強まったりもする。",
    "passageRuby": "ある行動(こうどう)を何度(なんど)も繰(く)り返(かえ)せば、それが自動化(じどうか)され、あまりそのことに思考(しこう)を向(む)けないようになっていくことが多(おお)いが、いつもそうなるとは限(かぎ)らない。例(たと)えば、人(ひと)との雑談(ざつだん)の中(なか)で、自分(じぶん)の考(かんが)えを率直(そっちょく)に述(の)べるということをいつもやっていれば、確(たし)かに<u>そのこと</u>は自動化(じどうか)され、自分(じぶん)の考(かんが)えを述(の)べようと特(とく)に意識(いしき)しないでも、気楽(きらく)に自分(じぶん)の考(かんが)えを話(はな)すような習慣(しゅうかん)ができる。\nしかし、もし、率直(そっちょく)に自分(じぶん)の考(かんが)えを述(の)べたときに、周囲(しゅうい)の人(ひと)から非難(ひなん)されたり、拒否(きょひ)されたりするということが繰(く)り返(かえ)されると、多(おお)くの場合(ばあい)、率直(そっちょく)に話(はな)すことは自分(じぶん)にマイナスになるという考(かんが)えが起(お)こって、率直(そっちょく)に話(はな)すという行動(こうどう)に自分(じぶん)でブレーキをかけるようになる。何回(なんかい)もブレーキをかけていると、ブレーキをかけること自体(じたい)が自動化(じどうか)して、自分(じぶん)では行動(こうどう)の結果(けっか)を取(と)り立(た)てて予期(よき)することなしに、なんとなく、率直(そっちょく)に発言(はつげん)することが少(すく)なくなり、おとなしくなるといった変化(へんか)が起(お)こってくる。<u>このような現象(げんしょう)</u>を行動(こうどう)の抑制(よくせい)の自動化(じどうか)という。\n行動(こうどう)の抑制(よくせい)の場合(ばあい)も、それが自動化(じどうか)すればするほど、思考(しこう)の果(は)たす役割(やくわり)は少(すく)なくなるのだが、思考(しこう)の仕方(しかた)や内容(ないよう)によって抑制(よくせい)の度合(どあ)いは変(か)わってくる。例(たと)えば、自分(じぶん)の述(の)べようとする意見(いけん)について、何回(なんかい)も繰(く)り返(かえ)し考(かんが)えていると、だんだん抑制(よくせい)が弱(よわ)まってきて、気楽(きらく)に発言(はつげん)できるようになることもあり、逆(ぎゃく)に、考(かんが)えれば考(かんが)えるほど、発言後(はつげんご)の嫌(いや)な予想(よそう)と結(むす)びつき、抑制(よくせい)が強(つよ)まったりもする。",
    "passageTrans": "어떤 행동을 몇 번이고 반복하면 그것이 자동화되어 그 일에 별로 사고를 기울이지 않게 되는 경우가 많지만, 언제나 그렇게 된다고는 할 수 없다. 예를 들어 사람들과의 잡담 속에서 자신의 생각을 솔직하게 말하는 일을 늘 하고 있으면, 확실히 그 일은 자동화되어 자신의 생각을 말하려고 특별히 의식하지 않더라도 부담 없이 자기 생각을 이야기하는 습관이 생긴다.\n그러나 만약 솔직하게 자신의 생각을 말했을 때 주변 사람들로부터 비난받거나 거부당하는 일이 반복되면, 대개의 경우 솔직하게 말하는 것은 자신에게 마이너스가 된다는 생각이 일어나 솔직하게 말한다는 행동에 스스로 브레이크를 걸게 된다. 여러 번 브레이크를 걸다 보면 브레이크를 거는 것 자체가 자동화되어, 스스로는 행동의 결과를 특별히 예기(예상)하지 않고도 왠지 모르게 솔직하게 발언하는 일이 줄어들고 얌전해지는 변화가 일어난다. 이러한 현상을 행동 억제의 자동화라고 한다.\n행동 억제의 경우에도 그것이 자동화되면 될수록 사고가 수행하는 역할은 적어지지만, 사고의 방식이나 내용에 따라 억제의 정도는 달라진다. 예를 들어 자신이 말하고자 하는 의견에 대해 몇 번이고 반복해서 생각하다 보면 점점 억제가 약해져서 편하게 발언할 수 있게 되기도 하고, 반대로 생각하면 할수록 발언 후의 불쾌한 예상과 결부되어 억제가 강해지기도 한다.",
