    "typeName": "중문 독해",
    "title": "'스승과 제자'와 '교사와 학생'의 본질적 차이 (「師と弟子」と「教師と生徒」)",
    "source": "Nihonez N1 실전 (2020.12 중문 3)",
    "wordCount": 550,
    "estimatedMinutes": 6,
    "passagePlain": "「教師と生徒」「師と弟子」は、位相（注1）は似ているがまったく質の異なるものだ。弟子は師を選べるが、生徒は教師を選べない。師も弟子を選べるが、教師は生徒を選べない。師はいわば固有の独りの人だが、教師はたくさんいるなかの偶然的な独りである。「師と弟子」は「教師と生徒」の煮つめられた（注2）模範ではない。「教師と生徒」は近代のものだが、「師と弟子」は思想（宗教）や武術や技能や芸術の世界には昔からあったもので、「特に卓越した人」からその「優れたもの」を真摯に学ぼうとするごく特殊な個別的なつながりである。「師と弟子」の場合、弟子は何を学ぼうとしているかははっきりと意識している。生徒の場合は、自分が学ぶことになる近代の膨大な知や生活や技術についてほとんど認知していない。\n「教師と生徒」は私（個人）と私（個人）のつながりではなく、公（社会的役割）と公（社会的役割）の関係であり、心的つながりは二次的なものである。個人と個人が求めあって結びついたものではなく、社会システムに媒介されたつながりである。それに対して、「師と弟子」はもともと個人的なつながりであり、「求めるもの」「到達すべきもの」「語るべきもの」を共有している。かなりの心的部分が同志的につながっていると考えられよう。「教師と生徒」のつながりの目的は、子ども（生徒）の市民（個人）形成に還元されるものであり、「師と弟子」というような濃い密度のつながりに昇華することは通常考えられない。\n\n(注1) 位相：ここでは、関係の形\n(注2) 煮つめられた：理想的な状態まで高められた",
    "passageRuby": "「教師(きょうし)と生徒(せいと)」「師(し)と弟子(でし)」は、位相(いそう)（注1）は似(に)ているがまったく質(しつ)の異(こと)なるものだ。弟子(でし)は師(し)を選(えら)べるが、生徒(せいと)は教師(きょうし)を選(えら)べない。師(し)も弟子(でし)を選(えら)べるが、教師(きょうし)は生徒(せいと)を選(えら)べない。師(し)はいわば固有(こゆう)の独(ひと)りの人(ひと)だが、教師(きょうし)はたくさんいるなかの偶然的(ぐうぜんてき)な独(ひと)りである。「師(し)と弟子(でし)」は「教師(きょうし)と生徒(せいと)」の煮(に)つめられた（注2）模範(もはん)ではない。「教師(きょうし)と生徒(せいと)」は近代(きんだい)のものだが、「師(し)と弟子(でし)」は思想(しそう)（宗教）や武術(ぶじゅつ)や技能(ぎのう)や芸術(げいじゅつ)の世界(せかい)には昔(むかし)からあったもので、<u>「特(とく)に卓越(たくえつ)した人(ひと)」からその「優(すぐ)れたもの」を真摯(しんし)に学(まな)ぼうとするごく特殊(とくしゅ)な個別的(こべつてき)なつながりである</u>。「師(し)と弟子(でし)」の場合(ばあい)、弟子(でし)は何(なに)を学(まな)ぼうとしているかははっきりと意識(いしき)している。生徒(せいと)の場合(ばあい)は、自分(じぶん)が学(まな)ぶことになる近代(きんだい)の膨大(ぼうだい)な知(ち)や生活(せいかつ)や技術(ぎじゅつ)についてほとんど認知(にんち)していない。\n「教師(きょうし)と生徒(せいと)」は私(わたくし)（個人）と私(わたくし)（個人）のつながりではなく、公(おおやけ)（社会的役割）と公(おおやけ)（社会的役割）の関係(かんけい)であり、心的(しんてき)つながりは二次的(にじてき)なものである。個人(こじん)と個人(こじん)が求(もと)めあって結(むす)びついたものではなく、社会(しゃかい)システムに媒介(ばいかい)されたつながりである。それに対(たい)して、「師(し)と弟子(でし)」はもともと個人的(こじんてき)なつながりであり、「求(もと)めるもの」「到達(とうたつ)すべきもの」「語(かた)るべきもの」を共有(きょうゆう)している。かなりの心的部分(しんてきぶぶん)が同志的(どうしてき)につながっていると考(かんが)えられよう。<u>「教師(きょうし)と生徒(せいと)」のつながりの目的(もくてき)は、子ども（生徒）の市民(しみん)（個人）形成(けいせい)に還元(かんげん)されるものであり</u>、「師(し)と弟子(でし)」というような濃(こ)い密度(みつど)のつながりに昇華(しょうか)することは通常考(つうじょうかんが)えられない。\n\n(注1) 位相(いそう)：ここでは、関係(かんけい)の形(かたち)\n(注2) 煮(に)つめられた：理想的(りそうてき)な状態(じょうたい)まで高(たか)められた",
    "passageTrans": "'교사와 학생', '스승과 제자'는 위상(주1)은 비슷하지만 전혀 질이 다른 것이다. 제자는 스승을 선택할 수 있지만 학생은 교사를 선택할 수 없다. 스승도 제자를 선택할 수 있지만 교사는 학생을 선택할 수 없다. 스승은 말하자면 고유한 단 한 사람이지만, 교사는 수많은 사람 중 우연적인 한 사람이다. '스승과 제자'는 '교사와 학생'이 이상적인 상태까지 응축된(주2) 모범이 아니다. '교사와 학생'은 근대의 산물이지만, '스승과 제자'는 사상(종교)이나 무술, 기능, 예술의 세계에 옛날부터 존재했던 것으로, '특히 탁월한 사람'으로부터 그 '뛰어난 것'을 진지하게 배우고자 하는 지극히 특수하고 개별적인 유대이다. '스승과 제자'의 경우 제자는 무엇을 배우려 하는지를 뚜렷이 의식하고 있다. 학생의 경우에는 자신이 배우게 될 근대의 방대한 지식이나 생활, 기술에 대해 거의 인지하지 못하고 있다.\n'교사와 학생'은 사(개인)와 사(개인)의 유대가 아니라 공(사회적 역할)과 공(사회적 역할)의 관계이며, 심적 유대는 이차적인 것이다. 개인과 개인이 서로 원해서 결합한 것이 아니라 사회 시스템에 매개된 유대이다. 그에 반해 '스승과 제자'는 본디 개인적인 유대이며, '추구하는 것', '도달해야 할 것', '논해야 할 것'을 공유하고 있다. 상당한 심적 부분이 동지적으로 연결되어 있다고 볼 수 있을 것이다. '교사와 학생'이라는 유대의 목적은 아이(학생)의 시민(개인) 형성으로 환원되는 것이며, '스승과 제자'와 같은 짙은 밀도의 유대로 승화하는 일은 통상 생각하기 어렵다.\n\n(주1) 위상: 여기서는 관계의 형태\n(주2) 응축된: 이상적인 상태까지 높아진",
