    "passagePlain": "地球の歴史を振り返ると、生物種の数は基本的には増加する傾向をたどってきた。約五億年前に生物種の「ビッグバン」とも呼ばれる爆発的な急増が起きた後、地球上の生命はこれまでに五回にわたる大絶滅を経験し、そのたびに種の数は急激に減少した。しかし、過去の大絶滅の後では、絶滅した生物に代わって生き残った別の生物が活動領域を広げ、その後比較的短時間のうちに種の数は増加に転じている。\nだが、現在進行している「六回目の大絶滅」の場合は状況がまったく異なる。過去の五回の大絶滅がいずれも隕石の衝突や気候変動といった自然現象によるものだったのに対し、今回の大絶滅は人間の活動が主な原因となっているからである。人間による森林伐採や乱獲、環境汚染などによって、現在の自然界での種の絶滅の速度は、自然状態の百倍から千倍という非常に速いものになっている。\nさらに深刻なのは、過去の大絶滅からの回復を支え、新たな生物種を生み出す「ゆりかご」の役割を果たしてきた熱帯林やサンゴ礁、湿地などの豊かな生息環境そのものが、人間の開発行為によって急速に破壊されていることだ。私たちがこれまでの行動パターンを改めず、このまま開発行為を続ければ、今世紀半ばには地球温暖化の影響も加わって種の絶滅にいっそう拍車が掛かり、生物多様性の減少と地球の生態系の破壊はさらに進んでいくだろう。",
    "passageRuby": "地球(ちきゅう)の歴史(れきし)を振(ふ)り返(かえ)ると、生物種(せいぶつしゅ)の数(かず)は基本的(きほんてき)には増加(ぞうか)する傾向(けいこう)をたどってきた。<u>約五億年前(やくごおくねんまえ)に生物種(せいぶつしゅ)の「ビッグバン」とも呼(よ)ばれる爆発的(ばくはつてき)な急増(きゅうぞう)が起(お)きた後(あと)、地球上(ちきゅうじょう)の生命(せいめい)はこれまでに五回(ごかい)にわたる大絶滅(だいぜつめつ)を経験(けいけん)し、そのたびに種(しゅ)の数(かず)は急激(きゅうげき)に減少(げんしょう)した。しかし、過去(かこ)の大絶滅(だいぜつめつ)の後(あと)では、絶滅(ぜつめつ)した生物(せいぶつ)に代(か)わって生(い)き残(のこ)った別(べつ)の生物(せいぶつ)が活動領域(かつどうりょういき)を広(ひろ)げ、その後比較的短時間(ごひかくてきたんじかん)のうちに種(しゅ)の数(かず)は増加(ぞうか)に転(てん)じている</u>。\nだが、現在進行(げんざいしんこう)している「六回目(ろっかいめ)の大絶滅(だいぜつめつ)」の場合(ばあい)は状況(じょうきょう)がまったく異(こと)なる。過去(かこ)の五回(ごかい)の大絶滅(だいぜつめつ)がいずれも隕石(いんせき)の衝突(しょうとつ)や気候変動(きこうへんどう)といった自然現象(しぜんげんしょう)によるものだったのに対(たい)し、今回(こんかい)の大絶滅(だいぜつめつ)は人間(にんげん)の活動(かつどう)が主(おも)な原因(げんいん)となっているからである。人間(にんげん)による森林伐採(しんりんばっさい)や乱獲(らんかく)、環境汚染(かんきょうおせん)などによって、現在(げんざい)の自然界(しぜんかい)での種(しゅ)の絶滅(ぜつめつ)の速度(そくど)は、自然状態(しぜんじょうたい)の百倍(ひゃくばい)から千倍(せんばい)という非常(ひじょう)に速(はや)いものになっている。\nさらに深刻(しんこく)なのは、過去(かこ)の大絶滅(だいぜつめつ)からの回復(かいふく)を支(ささ)え、新(あら)たな生物種(せいぶつしゅ)を生(う)み出(だ)す「ゆりかご」の役割(やくわり)を果(は)たしてきた熱帯林(ねったいりん)やサンゴ礁(しょう)、湿地(しっち)などの豊(ゆた)かな生息環境(せいそくかんきょう)そのものが、人間(にんげん)の開発行為(かいはつこうい)によって急速(きゅうそく)に破壊(はかい)されていることだ。私(わたし)たちがこれまでの行動(こうどう)パターンを改(あらた)めず、このまま開発行為(かいはつこうい)を続(つづ)ければ、今世紀半(こんせいきなか)ばには地球温暖化(ちきゅうおんだんか)の影響(えいきょう)も加(くわ)わって種(しゅ)の絶滅(ぜつめつ)にいっそう拍車(はくしゃ)が掛(か)かり、生物多様性(せいぶつたようせい)の減少(げんしょう)と地球(ちきゅう)の生態系(せいたいけい)の破壊(はかい)はさらに進(すす)んでいくだろう。",
    "passageTrans": "지구의 역사를 되돌아보면 생물종의 수는 기본적으로는 증가하는 경향을 밟아 왔다. 약 5억 년 전에 생물종의 '빅뱅'이라고도 불리는 폭발적인 급증이 일어난 뒤, 지구상의 생명은 지금까지 다섯 차례에 걸친 대절멸을 겪었으며 그때마다 종의 수는 급격히 감소했다. 그러나 과거의 대절멸 뒤에는 절멸한 생물을 대신해 살아남은 다른 생물이 활동 영역을 넓혔고, 그 후 비교적 단시간 내에 종의 수는 증가세로 돌아섰다.\n하지만 현재 진행되고 있는 '여섯 번째 대절멸'의 경우는 상황이 전혀 다르다. 과거 다섯 번의 대절멸이 모두 운석 충돌이나 기후 변동 같은 자연 현상에 의한 것이었던 데 반해, 이번 대절멸은 인간의 활동이 주된 원인이 되고 있기 때문이다. 인간에 의한 삼림 벌채나 남획, 환경 오염 등으로 인해 현재 자연계에서의 종의 절멸 속도는 자연 상태의 100배에서 1,000배라는 매우 빠른 수준이 되어 있다.\n더욱 심각한 것은 과거 대절멸로부터의 회복을 뒷받침하며 새로운 생물종을 탄생시키는 '요람' 역할을 해 온 열대림이나 산호초, 습지 같은 풍요로운 서식 환경 그 자체가 인간의 개발 행위로 인해 급속히 파괴되고 있다는 점이다. 우리가 지금까지의 행동 패턴을 고치지 않고 이대로 개발 행위를 계속한다면, 금세기 중반에는 지구 온난화의 영향까지 더해져 종의 절멸에 한층 박차가 가해지고, 생물다양성의 감소와 지구 생태계의 파괴는 더욱 진행될 것이다.",
