    "title": "정보 수집과 독창적 발상에 대한 두 시각 (情報収集と独創的な発想 - AとB)",
    "source": "Nihonez N1 실전 (2020.12 통합이해)",
    "wordCount": 540,
    "estimatedMinutes": 6,
    "passagePlain": "【A】\n情報化が進む現代において、仕事や学習で成果を上げるためには、できるだけ多くの情報を集めて分析することが大切だとイメージする人は少なくないでしょう。しかし、変化が激しく将来の予測が困難なこれからの時代においては、多くの情報を集めても、前提となる状況が変わってしまえばあまり役に立たなくなってしまう可能性があります。このような時代に必要なのは、ただ情報をかき集めることではなく、限られた情報からでも自分の頭で深く考え、他者とは異なる自分なりの発想を築き上げることです。既存の枠組みにとらわれない独創的なアイデアを生み出す力こそが求められているのです。\n\n【B】\n新しい企画やビジネスを生み出す際、まったくのゼロから何かを発明する必要はない。すでにある複数の要素を独自の視点で組み合わせることで、これまでになかった独創的なものを創造することは可能だ。そのためにもやはり、組み合わせの材料や土台となる情報が必要だ。現代は、どれだけ多くの情報を手にしているかで決まるといっても過言ではない。日頃から幅広い分野に関心を持ち、自ら積極的に多くの情報を集めようとする姿勢があってこそ、周りを驚かせるような新しいアイデアも生まれてくるのである。",
    "passageRuby": "【A】\n情報化(じょうほうか)が進(すす)む現代(げんだい)において、仕事(しごと)や学習(がくしゅう)で成果(せいか)を上(あ)げるためには、できるだけ多(おお)くの情報(じょうほう)を集(あつ)めて分析(ぶんせき)することが大切(たいせつ)だとイメージする人(ひと)は少(すく)なくないでしょう。しかし、変化(へんか)が激(はげ)しく将来(しょうらい)の予測(よそく)が困難(こんなん)なこれからの時代(じだい)においては、多(おお)くの情報(じょうほう)を集(あつ)めても、前提(ぜんてい)となる状況(じょうきょう)が変(か)わってしまえばあまり役(やく)に立(た)たなくなってしまう可能性(かのうせい)があります。<u>このような時代(じだい)に必要(ひつよう)なのは、ただ情報(じょうほう)をかき集(あつ)めることではなく、限(かぎ)られた情報(じょうほう)からでも自分(じぶん)の頭(あたま)で深(ふか)く考(かんが)え、他者(たしゃ)とは異(こと)なる自分(じぶん)なりの発想(はっそう)を築(きず)き上(あ)げることです</u>。既存(きそん)の枠組(わくぐ)みにとらわれない独創的(どくそうてき)なアイデアを生(う)み出(だ)す力(ちから)こそが求(もと)められているのです。\n\n【B】\n新(あたら)しい企画(きかく)やビジネスを生(う)み出(だ)す際(さい)、まったくのゼロから何(なに)かを発明(はつめい)する必要(ひつよう)はない。すでにある複数(ふくすう)の要素(ようそ)を独自(どくじ)の視点(してん)で組(く)み合(あ)わせることで、これまでになかった独創的(どくそうてき)なものを創造(そうぞう)することは可能(かのう)だ。<u>そのためにもやはり、組(く)み合(あ)わせの材料(ざいりょう)や土台(どだい)となる情報(じょうほう)が必要(ひつよう)だ。現代(げんだい)は、どれだけ多(おお)くの情報(じょうほう)を手(て)にしているかで決(き)まるといっても過言(かごん)ではない</u>。日頃(ひごろ)から幅広(はばひろ)い分野(ぶんや)に関心(かんしん)を持(も)ち、自(みずか)ら積極的(せっきょくてき)に多(おお)くの情報(じょうほう)を集(あつ)めようとする姿勢(しせい)があってこそ、周(まわ)りを驚(おどろ)かせるような新(あたら)しいアイデアも生(う)まれてくるのである。",
    "passageTrans": "【A】\n정보화가 진행되는 현대에 있어서 일이나 학습에서 성과를 올리기 위해서는 가능한 한 많은 정보를 모아 분석하는 것이 중요하다고 생각하는 사람이 적지 않을 것입니다. 그러나 변화가 격렬하고 장래 예측이 곤란한 앞으로의 시대에는 많은 정보를 모으더라도 전제가 되는 상황이 바뀌어 버리면 별로 쓸모없어질 가능성이 있습니다. 이러한 시대에 필요한 것은 그저 정보를 긁어모으는 것이 아니라, 한정된 정보로부터라도 자신의 머리로 깊이 생각하여 타자와는 다른 자기 나름의 발상을 구축하는 것입니다. 기존의 틀에 얽매이지 않는 독창적인 아이디어를 만들어 내는 힘이야말로 요구되고 있는 것입니다.\n\n【B】\n새로운 기획이나 비즈니스를 창출할 때 완전한 제로 상태에서 무언가를 발명할 필요는 없다. 이미 존재하는 복수의 요소를 독자적인 시점으로 조합함으로써 지금까지 없었던 독창적인 것을 창조하는 것은 가능하다. 그러기 위해서도 역시 조합의 재료나 토대가 되는 정보가 필요하다. 현대는 얼마나 많은 정보를 손에 쥐고 있는가로 결정된다고 해도 과언이 아니다. 평소부터 폭넓은 분야에 관심을 가지고 스스로 적극적으로 많은 정보를 모으려는 자세가 있어야만 비로소 주변을 놀라게 할 만한 새로운 아이디어도 탄생하는 것이다.",
