    "passageRuby": "子(こ)どもたちは、教師(きょうし)から「自分(じぶん)で考(かんが)えなさい」「人(ひと)の真似(まね)をしてはいけません」ということを明示的(めいじてき)にも、暗黙的(あんもくてき)にも示(しめ)されると、「人(ひと)の真似(まね)ではない」という「真似(まね)」をすることを学(まな)ぶようになる。例(たと)えば、自分自身(じぶんじしん)の気持(きも)ちとは裏腹(うらはら)に、あえて「人(ひと)とは異(こと)なる発言(はつげん)、あるいは行動(こうどう)をする」ことを学(まな)んでいく。この学(まな)びが模倣(もほう)ではないとどうして言(い)えようか。一見個性的(いっけんこせいてき)、一見創造的(いっけんそうぞうてき)に見(み)える<u>仮面(かめん)をつけた模倣(もほう)</u>は、明(あき)らかな「形(かたち)」の模倣(もほう)とは異(こと)なる故(ゆえ)に、その実体(じったい)が見(み)えにくい。",
    "passageTrans": "아이들은 교사로부터 '스스로 생각하세요', '남을 흉내 내서는 안 됩니다'라는 말을 명시적으로나 암묵적으로 지시받으면, '남의 흉내가 아니다'라는 '흉내'를 내는 법을 배우게 된다. 예를 들어 자기 자신의 마음과는 정반대로 굳이 '남과는 다른 발언 혹은 행동을 하는' 것을 배워 나간다. 이 배움이 모방이 아니라고 어찌 말할 수 있겠는가. 언뜻 개성적이고 언뜻 창조적으로 보이는 <u>가면을 쓴 모방</u>은 명백한 '형태'의 모방과는 다르기 때문에 그 실체가 보이기 어렵다.",
