    "title": "개구리의 종 다양성과 기생충의 공존 (カエルの種多様性と寄生虫の共存)",
    "source": "Nihonez N1 실전 (2019.12 중문 2)",
    "wordCount": 520,
    "estimatedMinutes": 6,
    "passagePlain": "イギリスの科学誌『ネイチャー』の最近の号に、カエルの種多様性と寄生虫の感染率についての論文が載っています。カエルの全数は同じで、特定の1種類しかいない場合と、数種類のカエルが共存する場合で、ある種のカエルが寄生虫に感染して発病する割合は、前者のケースのほうが高いという内容です。つまり多様性が高いと特定の種が病気になる割合が下がるというのです。\n\n他の種が存在することによって自分が病気になる確率が下がるとするのなら、それぞれの種は互いの種を競争で滅ぼしてしまわないほうが自分も得をします。もしかすると、自分たちの使う資源を他の種に譲ってでも、それを存続させることが有利になるかもしれません。アリのような種内での協力と同様、いくつもの種がコストを払って共存し合うことで、それぞれの種が得をしている可能性があります。<u>種のレベルを超えた協力</u>と言えるかもしれません。\n\nこの話がさらに面白いのは、それが寄生虫という、カエルを滅ぼしかねない要因とリンクして起こっている点です。寄生虫の側から見た場合、感受性の（感染する）カエル1種だけのときは、どの個体へも感染でき、そこで成長できますから、短期的な寄生虫の増殖率は高くなるでしょう。しかし、全部のカエルに感染して殺してしまうと寄生できる相手がいなくなるため、寄生虫も滅びなくてはならなくなります。したがって、いろいろなカエルが存在するほうが寄生虫にとっても自身の長期的存続を可能にするメカニズムとして働いているのです。",
    "passageRuby": "イギリスの科学誌(かがくし)『ネイチャー』の最近(さいきん)の号(ごう)に、カエルの種多様性(しゅたようせい)と寄生虫(きせいちゅう)の感染率(かんせんりつ)についての論文(ろんぶん)が載(の)っています。カエルの全数(ぜんすう)は同(おな)じで、特定(とくてい)の1種類(しゅるい)しかいない場合(ばあい)と、数種類(すうしゅるい)のカエルが共存(きょうぞん)する場合(ばあい)で、ある種(しゅ)のカエルが寄生虫(きせいちゅう)に感染(かんせん)して発病(はつびょう)する割合(わりあい)は、前者(ぜんしゃ)のケースのほうが高(たか)いという内容(ないよう)です。つまり多様性(たようせい)が高(たか)いと特定(とくてい)の種(しゅ)が病気(びょうき)になる割合(わりあい)が下(さ)がるというのです。\n\n他(ほか)の種(しゅ)が存在(そんざい)することによって自分(じぶん)が病気(びょうき)になる確率(かくりつ)が下(さ)がるとするのなら、それぞれの種(しゅ)は互(たが)いの種(しゅ)を競争(きょうそう)で滅(ほろ)ぼしてしまわないほうが自分(じぶん)も得(とく)をします。もしかすると、自分(じぶん)たちの使(つか)う資源(しげん)を他(ほか)の種(しゅ)に譲(ゆず)ってでも、それを存続(そんぞく)させることが有利(ゆうり)になるかもしれません。アリのような種内(しゅない)での協力(きょうりょく)と同様(どうよう)、いくつもの種(しゅ)がコストを払(はら)って共存(きょうぞん)し合(あ)うことで、それぞれの種(しゅ)が得(とく)をしている可能性(かのうせい)があります。<u>種(しゅ)のレベルを超(こ)えた協力(きょうりょく)</u>と言(い)えるかもしれません。\n\nこの話(はなし)がさらに面白(おもしろ)いのは、それが寄生虫(きせいちゅう)という、カエルを滅(ほろ)ぼしかねない要因(よういん)とリンクして起(お)こっている点(てん)です。寄生虫(きせいちゅう)の側(がわ)から見(み)た場合(ばあい)、感受性(かんじゅせい)の（感染(かんせん)する）カエル1種(しゅ)だけのときは、どの個体(こたい)へも感染(かんせん)でき、そこで成長(せいちょう)できますから、短期的(たんきてき)な寄生虫(きせいちゅう)の増殖率(ぞうしょくりつ)は高(たか)くなるでしょう。しかし、全部(ぜんぶ)のカエルに感染(かんせん)して殺(ころ)してしまうと寄生(きせい)できる相手(あいて)がいなくなるため、寄生虫(きせいちゅう)も滅(ほろ)びなくてはならなくなります。したがって、いろいろなカエルが存在(そんざい)するほうが寄生虫(きせいちゅう)にとっても自身(じしん)の長期的存続(ちょうきてきそんぞく)を可能(かのう)にするメカニズムとして働(はたら)いているのです。",
    "passageTrans": "영국의 과학지 『네이처』 최근호에 개구리의 종 다양성과 기생충 감염률에 관한 논문이 실려 있습니다. 개구리의 전체 개체 수는 같고 특정 1종류만 있는 경우와 여러 종류의 개구리가 공존하는 경우를 비교했을 때, 어떤 종의 개구리가 기생충에 감염되어 발병하는 비율은 전자(특정 1종류만 있는 경우)가 더 높다는 내용입니다. 즉 다양성이 높으면 특정 종이 병에 걸리는 비율이 낮아진다는 것입니다.\n\n다른 종이 존재함으로써 자신이 병에 걸릴 확률이 낮아진다면, 각각의 종은 서로의 종을 경쟁으로 멸종시키지 않는 편이 자신에게도 이득이 됩니다. 어쩌면 자신들이 쓸 자원을 다른 종에게 양보해서라도 그 종을 존속시키는 것이 유리할지도 모릅니다. 개미와 같은 종 내부에서의 협력과 마찬가지로, 여러 종이 비용(코스트)을 지불하며 공존함으로써 각각의 종이 이득을 얻고 있을 가능성이 있습니다. <u>종의 차원을 넘어선 협력</u>이라 말할 수 있을지도 모릅니다.\n\n이 이야기가 더욱 흥미로운 점은 그것이 기생충이라는, 개구리를 멸종시킬 수도 있는 요인과 연결되어 일어나고 있다는 점입니다. 기생충의 입장에서 보았을 때, 감수성이 있는(감염되는) 개구리가 1종뿐일 때는 어느 개체에나 감염되어 그곳에서 성장할 수 있으므로 단기적인 기생충의 증식률은 높아질 것입니다. 그러나 모든 개구리에게 감염되어 죽여 버리면 기생할 숙주가 없어지기 때문에 기생충도 멸종하지 않을 수 없게 됩니다. 따라서 여러 종류의 개구리가 존재하는 편이 기생충에게도 자신의 장기적 존속을 가능하게 하는 메커니즘으로 작용하고 있는 것입니다.",
