    "typeName": "통합 이해",
    "title": "부하 직원을 칭찬하는 방법과 리더의 자세 (部下の褒め方と接し方)",
    "source": "Nihonez N1 실전 (2019.12 통합이해)",
    "wordCount": 600,
    "estimatedMinutes": 7,
    "passagePlain": "【A】\n褒めれば人は育つといいます。確かに人間は叱られるより、認められたり褒められたほうが嬉しいに決まっていますし、「よし、次もがんばろう」とやる気も出るものです。リーダーだって、普段からガミガミ言うより、部下を褒めるほうが自分自身の気分も良いでしょう。\nしかし褒めてばかりいると、今度は思わぬ弊害が出てくると私は考えています。確かに部下の士気は上がるのですが、逆に褒められることが目的になりかねない。「お前は偉いな」と課長に褒められたいから、仕事を一生懸命にやるようになってしまうのです。そして褒められないとやる気を失い、不満を抱くようになってしまいます。「良くやった」「偉いな」などという言葉は、たまに言うから効果的なのであって、日常的に口にしていたら効果は半減してしまうでしょう。要は褒めるところと叱るところ、リーダーはいつも人を見てバランスを考えなくてはなりません。\n\n【B】\n部下のやる気を引き出すようにうまく褒めるのは難しい。的外れな褒め方をすれば「自分をよく見ていない」と不信感を抱かせてしまうし、皆の前で特定の者ばかりを褒めれば、チーム内の関係が悪化してしまうこともある。さらに褒め続けることで、部下が、仕事への責任感や使命感からではなく、上司に褒められることを目的にがんばるという状態になってしまう恐れがある。\nこのような事態を避けるために、上司には適切に褒める技術が求められる。部下が良い仕事をしたら、タイミングを逃さずその場で褒めることが効果的だ。また、成果だけを褒めるのではなく、仕事の過程の中で何が良かったかを取り上げて褒めることが重要だ。そうすれば、部下も評価された点を明確に自覚でき、次の仕事につなげやすくなる。",
    "passageRuby": "【A】\n褒(ほ)めれば人(ひと)は育(そだ)つといいます。確(たし)かに人間(にんげん)は叱(しか)られるより、認(みと)められたり褒(ほ)められたほうが嬉(うれ)しいに決(き)まっていますし、「よし、次(つぎ)もがんばろう」とやる気(き)も出(で)るものです。リーダーだって、普段(ふだん)からガミガミ言(い)うより、部下(ぶか)を褒(ほ)めるほうが自分自身(じぶんじしん)の気分(きぶん)も良(よ)いでしょう。\nしかし褒(ほ)めてばかりいると、今度(こんど)は思(おも)わぬ弊害(へいがい)が出(で)てくると私(わたし)は考(かんが)えています。確(たし)かに部下(ぶか)の士気(しき)は上(あ)がるのですが、逆(ぎゃく)に褒(ほ)められることが目的(もくてき)になりかねない。「お前(まえ)は偉(えら)いな」と課長(かちょう)に褒(ほ)められたいから、仕事(しごと)を一生懸命(いっしょうけんめい)にやるようになってしまうのです。そして褒(ほ)められないとやる気(き)を失(うしな)い、不満(ふまん)を抱(いだ)くようになってしまいます。「良(よ)くやった」「偉(えら)いな」などという言葉(ことば)は、たまに言(い)うから効果的(こうかてき)なのであって、日常的(にちじょうてき)に口(くち)にしていたら効果(こうか)は半減(はんげん)してしまうでしょう。要(よう)は褒(ほ)めるところと叱(しか)るところ、リーダーはいつも人(ひと)を見(み)てバランスを考(かんが)えなくてはなりません。\n\n【B】\n部下(ぶか)のやる気(き)を引(ひ)き出(だ)すようにうまく褒(ほ)めるのは難(むずか)しい。的外(まとはず)れな褒(ほ)め方(かた)をすれば「自分(じぶん)をよく見(み)ていない」と不信感(ふしんかん)を抱(いだ)かせてしまうし、皆(みな)の前(まえ)で特定(とくてい)の者(もの)ばかりを褒(ほ)めれば、チーム内(ない)の関係(かんけい)が悪化(あっか)してしまうこともある。さらに褒(ほ)め続(つづ)けることで、部下(ぶか)が、仕事(しごと)への責任感(せきにんかん)や使命感(しめいかん)からではなく、上司(じょうし)に褒(ほ)められることを目的(もくてき)にがんばるという状態(じょうたい)になってしまう恐(おそ)れがある。\nこのような事態(じたい)を避(さ)けるために、上司(じょうし)には適切(てきせつ)に褒(ほ)める技術(ぎじゅつ)が求(もと)められる。部下(ぶか)が良(よ)い仕事(しごと)をしたら、タイミングを逃(のが)さずその場(ば)で褒(ほ)めることが効果的(こうかてき)だ。また、成果(せいか)だけを褒(ほ)めるのではなく、仕事(しごと)の過程(かてい)の中(なか)で何(なに)が良(よ)かったかを取(と)り上(あ)げて褒(ほ)めることが重要(じゅうよう)だ。そうすれば、部下(ぶか)も評価(ひょうか)された点(てん)を明確(めいかく)に自覚(じかく)でき、次(つぎ)の仕事(しごと)につなげやすくなる。",
    "passageTrans": "【A】\n칭찬하면 사람은 성장한다고들 합니다. 확실히 인간은 꾸중을 듣는 것보다 인정받거나 칭찬받는 편이 기쁘기 마련이고, '좋아, 다음에도 열심히 하자'라며 의욕도 생기는 법입니다. 리더로서도 평소 사사건건 잔소리를 하는 것보다 부하를 칭찬하는 편이 자기 자신의 기분도 좋을 것입니다.\n그러나 칭찬만 하고 있으면 이번에는 뜻밖의 폐해가 나타난다고 저는 생각합니다. 확실히 부하의 사기는 오르지만, 반대로 칭찬받는 것이 목적이 될 우려가 있습니다. '자네 대단하군' 하고 과장에게 칭찬받고 싶어서 일을 열심히 하게 되어 버리는 것입니다. 그리고 칭찬받지 못하면 의욕을 잃고 불만을 품게 됩니다. '잘했어', '대단하네' 같은 말은 가끔 하니까 효과적인 것이지, 일상적으로 입에 올리면 효과는 반감되고 말 것입니다. 요컨대 칭찬할 부분과 꾸짖을 부분, 리더는 언제나 사람을 살펴 균형을 생각하지 않으면 안 됩니다.\n\n【B】\n부하의 의욕을 끌어내도록 능숙하게 칭찬하기란 어렵다. 초점이 빗나간 칭찬을 하면 '나를 제대로 보고 있지 않다'며 불신감을 품게 만들고, 모두의 앞에서 특정 인물만 칭찬하면 팀 내 관계가 악화되기도 한다. 나아가 계속 칭찬함으로써 부하가 일에 대한 책임감이나 사명감에서가 아니라 상사에게 칭찬받는 것을 목적으로 열심히 하는 상태가 되어 버릴 우려가 있다.\n이러한 사태를 피하기 위해 상사에게는 적절히 칭찬하는 기술이 요구된다. 부하가 좋은 일을 해냈다면 타이밍을 놓치지 않고 그 자리에서 칭찬하는 것이 효과적이다. 또한 성과만을 칭찬하는 것이 아니라 업무 과정 속에서 무엇이 좋았는지를 짚어 칭찬하는 것이 중요하다. 그렇게 하면 부하도 평가받은 점을 명확히 자각할 수 있어 다음 업무로 이어 가기 쉬워진다.",
